DG.put("krisnaavtaar/22",{"n":22,"title":"ਅਥ ਲੁਕ ਮੀਚਨ ਖੇਲ ਕਥਨੰ","title_roman":"Ath luk meechan khel kathnan","page":367,"blocks":[{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":367},{"type":"verse","number":[228],"number_text":"੨੨੮।","page":367,"lines":[{"gurmukhi":"ਮਾਰਿ ਪ੍ਰਲੰਬ ਲਯੋ ਮੁਸਲੀ ਜਬ ਯਾਦ ਕਰੀ ਹਰਿ ਜੀ ਤਬ ਗਾਈ।","roman":"Maari pralanb layo muslee jab yaad karee hari jee tab gaaee |","meaning_en":"","page":367},{"gurmukhi":"ਚੂਮਨ ਲਾਗ ਤਬੈ ਬਛਰਾ ਮੁਖ ਧੇਨ ਵਹੈ ਉਨ ਕੀ ਅਰੁ ਮਾਈ।","roman":"Chooman laag tabai bachhraa mukh dhen vahai un kee aru maaee |","meaning_en":"","page":367},{"gurmukhi":"ਹੋਇ ਪ੍ਰਸੰਨ੍ਯ ਤਬੈ ਕਰੁਨਾਨਿਧ ਤਉ ਲੁਕ ਮੀਚਨ ਖੇਲ ਮਚਾਈ।","roman":"Hoi prasanny tabai karunaanidh tau luk meechan khel machaaee |","meaning_en":"","page":367},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਕੇ ਮਨ ਮੈ ਬਹੁ ਭਾਤਿਨ ਭਾਈ। ੨੨੮।","roman":"Taa chhabi kee ati hee upmaa kabi ke man mai bahu bhaatin bhaaee | 228 |","meaning_en":"","page":367}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":367},{"type":"verse","number":[229],"number_text":"੨੨੯।","page":367,"lines":[{"gurmukhi":"ਬੈਠਿ ਕਰਿ ਗ੍ਵਾਰ ਆਖੈ ਮੀਚੈ ਏਕ ਗ੍ਵਾਰ ਹੂੰ ਕੀ","roman":"Baithi kari gvaar aakhai meechai ek gvaar hoon kee","meaning_en":"","page":367},{"gurmukhi":"ਛੋਰਿ ਦੇਤ ਤਾ ਕੋ ਸੋ ਤੋ ਅਉਰੋ ਗਹੈ ਧਾਇ ਕੈ।","roman":"Chhori det taa ko so to auro gahai dhaai kai |","meaning_en":"","page":367},{"gurmukhi":"ਆਖੈ ਮੂੰਦਤ ਹੈ ਤਬ ਓਹੀ ਗੋਪ ਹੂੰ ਕੀ ਫੇਰਿ","roman":"Aakhai moondat hai tab ohee gop hoon kee pheri","meaning_en":"","page":367},{"gurmukhi":"ਜਾ ਕੇ ਤਨ ਕੋ ਜੋ ਛੁਐ ਕਰ ਸਾਥ ਜਾਇ ਕੈ।","roman":"Jaa ke tan ko jo chhuai kar saath jaai kai |","meaning_en":"","page":367},{"gurmukhi":"ਤਹ ਤੋ ਛਲ ਬਲ ਕੈ ਪਲਾਵੈ ਹਾਥਿ ਆਵੈ ਨਹੀ","roman":"Tah to chhal bal kai palaavai haathi aavai nahee","meaning_en":"","page":367},{"gurmukhi":"ਤਉ ਮਿਟਾਵੈ ਆਖੈ ਆਪ ਹੀ ਤੇ ਸੋ ਤੋ ਆਇ ਕੈ।","roman":"Tau mitaavai aakhai aap hee te so to aai kai |","meaning_en":"","page":367},{"gurmukhi":"ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਤਾ ਕੀ ਮਹਿਮਾ ਨ ਲਖੀ ਜਾਇ","roman":"Kahai kabi syaam taa kee mahimaa na lakhee jaai","meaning_en":"","page":367},{"gurmukhi":"ਐਸੀ ਭਾਤਿ ਖੇਲੈ ਕਾਨ੍ਹ ਮਹਾ ਸੁਖੁ ਪਾਇ ਕੈ।੨੨੯।","roman":"Aisee bhaati khelai kaanh mahaa sukhu paai kai | 229 |","meaning_en":"","page":367}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":367},{"type":"verse","number":[230],"number_text":"੨੩੦।","page":367,"lines":[{"gurmukhi":"ਅੰਤ ਭਏ ਰੁਤਿ ਗ੍ਰੀਖਮ ਕੀ ਰੁਤਿ ਪਾਵਸ ਆਇ ਗਈ ਸੁਖਦਾਈ।","roman":"Ant bhae ruti greekham kee ruti paavas aai gaee sukhdaaee |","meaning_en":"","page":367},{"gurmukhi":"ਕਾਨ੍ਹ ਫਿਰੈ ਬਨ ਬੀਥਿਨ ਮੈ ਸੰਗਿ ਲੈ ਬਛਰੇ ਤਿਨ ਕੀ ਅਰੁ ਮਾਈ।","roman":"Kaanh phirai ban beethin mai sangi lai bachhre tin kee aru maaee |","meaning_en":"","page":367},{"gurmukhi":"ਬੈਠਿ ਤਬੈ ਫਿਰਿ ਮਧ ਗੁਫਾ ਗਿਰਿ ਗਾਵਤ ਗੀਤ ਸਭੈ ਮਨੁ ਭਾਈ।","roman":"Baithi tabai phiri madh guphaa giri gaavat geet sabhai manu bhaaee |","meaning_en":"","page":367},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਭਾਖਿ ਸੁਨਾਈ। ੨੩੦।","roman":"Taa chhabi kee ati hee upmaa kabi ne mukh te im bhaakhi sunaaee | 230 |","meaning_en":"","page":367}]},{"type":"verse","number":[231],"number_text":"੨੩੧।","page":367,"lines":[{"gurmukhi":"ਸੋਰਠਿ ਸਾਰੰਗ ਅਉ ਗੁਜਰੀ ਲਲਤਾ ਅਰੁ ਭੈਰਵ ਦੀਪਕ ਗਾਵੈ।","roman":"Sorthi saarang au gujree laltaa aru bhairav deepak gaavai |","meaning_en":"","page":367},{"gurmukhi":"ਟੋਡੀ ਅਉ ਮੇਘ ਮਲ੍ਹਾਰ ਅਲਾਪਤ ਗੌਡ ਅਉ ਸੁਧ ਮਲ੍ਹਾਰ ਸੁਨਾਵੈ।","roman":"Todee au megh malhaar alaapat gaud au sudh malhaar sunaavai |","meaning_en":"","page":367},{"gurmukhi":"ਜੈਤਸਰੀ ਅਰੁ ਮਾਲਸਿਰੀ ਅਉ ਪਰਜ ਸੁ ਰਾਗਸਿਰੀ ਠਟ ਪਾਵੈ।","roman":"Jaitasree aru maalsiree au paraj su raagsiree that paavai |","meaning_en":"","page":367},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਜੀ ਰਿਝ ਕੈ ਮੁਰਲੀ ਸੰਗ ਕੋਟਕ ਰਾਗ ਬਜਾਵੈ। ੨੩੧।","roman":"Syaam kahai hari jee rijh kai murlee sang kotak raag bajaavai | 231 |","meaning_en":"","page":367}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":368},{"type":"verse","number":[232],"number_text":"੨੩੨।","page":368,"lines":[{"gurmukhi":"ਲਲਤ ਧਨਾਸਰੀ ਬਜਾਵਹਿ ਸੰਗਿ ਬਾਸੁਰੀ ਕਿਦਾਰਾ ਔਰ ਮਾਲਵਾ ਬਿਹਾਗੜਾ ਅਉ ਗੂਜਰੀ।","roman":"Lalat dhanaasree bajaavhi sangi baasuree kidaaraa aur maalvaa bihaagraa au goojree |","meaning_en":"","page":368},{"gurmukhi":"ਮਾਰੂ ਅਉ ਪਰਜ ਔਰ ਕਾਨੜਾ ਕਲਿਆਨ ਸੁਭ ਕੁਕਭ ਬਿਲਾਵਲੁ ਸੁਨੈ ਤੇ ਆਵੈ ਮੂਜਰੀ।","roman":"Maaroo au paraj aur kaanraa kaliaan subh kukabh bilaavlu sunai te aavai moojree |","meaning_en":"","page":368},{"gurmukhi":"ਭੈਰਵ ਪਲਾਸੀ ਭੀਮ ਦੀਪਕ ਸੁ ਗਉਰੀ ਨਟ ਠਾਢੋ ਦ੍ਰੁਮ ਛਾਇ ਮੈ ਸੁ ਗਾਵੈ ਕਾਨ੍ਹ ਪੂਜਰੀ।","roman":"Bhairav palaasee bheem deepak su gauree nat thaadho drum chhaai mai su gaavai kaanh poojree |","meaning_en":"","page":368},{"gurmukhi":"ਤਾਤੇ ਗ੍ਰਿਹ ਤਿਆਗਿ ਤਾ ਕੀ ਸੁਨਿ ਧੁਨਿ ਸ੍ਰੋਨਨ ਮੈ ਮ੍ਰਿਗਨੈਨੀ ਫਿਰਤ ਸੁ ਬਨਿ ਬਨਿਊਜਰੀ।੨੩੨।","roman":"Taate grih tiaagi taa kee suni dhuni sronan mai mrignainee phirat su bani banioojree | 232 |","meaning_en":"","page":368}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":368},{"type":"verse","number":[233],"number_text":"੨੩੩।","page":368,"lines":[{"gurmukhi":"ਸੀਤ ਭਈ ਰੁਤਿ ਕਾਤਿਕ ਕੀ ਮੁਨਿ ਦੇਵ ਚੜਿਓ ਜਲ ਹ੍ਵੈ ਗਯੋ ਥੋਰੋ।","roman":"Seet bhaee ruti kaatik kee muni dev chario jal hvai gayo thoro |","meaning_en":"","page":368},{"gurmukhi":"ਕਾਨ੍ਹ ਕਨੀਰੇ ਕੇ ਫੂਲ ਧਰੇ ਅਰੁ ਗਾਵਤ ਬੇਨ ਬਜਾਵਤ ਭੋਰੋ।","roman":"Kaanh kaneere ke phool dhare aru gaavat ben bajaavat bhoro |","meaning_en":"","page":368},{"gurmukhi":"ਸ੍ਯਾਮ ਕਿਧੋ ਉਪਮਾ ਤਿਹ ਕੀ ਮਨ ਮਧਿ ਬਿਚਾਰੁ ਕਬਿਤੁ ਸੁ ਜੋਰੋ।","roman":"Syaam kidho upmaa tih kee man madhi bichaaru kabitu su joro |","meaning_en":"","page":368},{"gurmukhi":"ਮੈਨ ਉਠਿਯੋ ਜਗਿ ਕੈ ਤਿਨ ਕੈ ਤਨਿ ਲੇਤ ਹੈ ਪੇਚ ਮਨੋ ਅਹਿ ਤੋਰੋ। ੨੩੩।","roman":"Main uthiyo jagi kai tin kai tani let hai pech mano ahi toro | 233 |","meaning_en":"","page":368}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":368},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":368},{"type":"verse","number":[234],"number_text":"੨੩੪।","page":368,"lines":[{"gurmukhi":"ਬੋਲਤ ਹੈ ਮੁਖ ਤੇ ਸਭ ਗਵਾਰਿਨ ਪੁੰਨਿ ਕਰਿਓ ਇਨ ਹੂੰ ਅਤਿ ਮਾਈ।","roman":"Bolat hai mukh te sabh gavaarin punni kario in hoon ati maaee |","meaning_en":"","page":368},{"gurmukhi":"ਜਗ੍ਯ ਕਰਿਯੋ ਕਿ ਕਰਿਯੋ ਤਪ ਤੀਰਥ ਗੰਧ੍ਰਬ ਤੇ ਇਨ ਕੈ ਸਿਛ ਪਾਈ।","roman":"Jagy kariyo ki kariyo tap teerath gandhrab te in kai sichh paaee |","meaning_en":"","page":368},{"gurmukhi":"ਕੈ ਕਿ ਪੜੀ ਸਿਤਬਾਨਹੁ ਤੇ ਕਿ ਕਿਧੋ ਚਤੁਰਾਨਨਿ ਆਪ ਬਨਾਈ।","roman":"Kai ki paree sitbaanhu te ki kidho chaturaanni aap banaaee |","meaning_en":"","page":368},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਉਪਮਾ ਤਿਹ ਕੀ ਇਹ ਤੇ ਹਰਿ ਓਠਨ ਸਾਥ ਲਗਾਈ। ੨੩੪।","roman":"Syaam kahai upmaa tih kee ih te hari othan saath lagaaee | 234 |","meaning_en":"","page":368}]},{"type":"verse","number":[235],"number_text":"੨੩੫।","page":368,"lines":[{"gurmukhi":"ਸੁਤ ਨੰਦ ਬਜਾਵਤ ਹੈ ਮੁਰਲੀ ਉਪਮਾ ਤਿਹ ਕੀ ਕਬਿ ਸ੍ਯਾਮ ਗਨੋ।","roman":"Sut nand bajaavat hai murlee upmaa tih kee kabi syaam gano |","meaning_en":"","page":368},{"gurmukhi":"ਤਿਹ ਕੀ ਧੁਨਿ ਕੋ ਸੁਨਿ ਮੋਹ ਰਹੇ ਮੁਨਿ ਰੀਝਤ ਹੈ ਸੁ ਜਨੋ ਰੁ ਕਨੋ।","roman":"Tih kee dhuni ko suni moh rahe muni reejhat hai su jano ru kano |","meaning_en":"","page":368},{"gurmukhi":"ਤਨ ਕਾਮ ਭਰੀ ਗੁਪੀਆ ਸਭ ਹੀ ਮੁਖ ਤੇ ਇਹ ਭਾਤਨ ਜਵਾਬ ਭਨੋ।","roman":"Tan kaam bharee gupeeaa sabh hee mukh te ih bhaatan javaab bhano |","meaning_en":"","page":368},{"gurmukhi":"ਮੁਖ ਕਾਨ੍ਹ ਗੁਲਾਬ ਕੋ ਫੂਲ ਭਯੋ ਇਹ ਨਾਲਿ ਗੁਲਾਬ ਚੁਆਤ ਮਨੋ। ੨੩੫।","roman":"Mukh kaanh gulaab ko phool bhayo ih naali gulaab chuaat mano | 235 |","meaning_en":"","page":368}]},{"type":"verse","number":[236],"number_text":"੨੩੬।","page":368,"lines":[{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਸੁਨਿ ਕੈ ਧੁਨਿ ਕੌ ਮ੍ਰਿਗ ਮੋਹਿ ਪਸਾਰ ਗੇ ਖਗ ਪੈ ਪਖਾ।","roman":"Mohi rahe suni kai dhuni kau mrig mohi pasaar ge khag pai pakhaa |","meaning_en":"","page":368},{"gurmukhi":"ਨੀਰ ਬਹਿਓ ਜਮੁਨਾ ਉਲਟੋ ਪਿਖਿ ਕੈ ਤਿਹ ਕੋ ਨਰ ਖੋਲ ਰੇ ਚਖਾ।","roman":"Neer bahio jamunaa ulto pikhi kai tih ko nar khol re chakhaa |","meaning_en":"","page":368},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਤਿਨ ਕੋ ਸੁਨਿ ਕੈ ਬਛੁਰਾ ਮੁਖ ਸੋ ਕਛੁ ਨ ਚੁਗੈ ਕਖਾ।","roman":"Syaam kahai tin ko suni kai bachhuraa mukh so kachhu na chugai kakhaa |","meaning_en":"","page":368},{"gurmukhi":"ਛੋਡਿ ਚਲੀ ਪਤਨੀ ਅਪਨੇ ਪਤਿ ਤਾਰਕ ਹ੍ਵੈ ਜਿਮ ਡਾਰਤ ਲਖਾ। ੨੩੬।","roman":"Chhodi chalee patnee apne pati taarak hvai jim daarat lakhaa | 236 |","meaning_en":"","page":368}]},{"type":"verse","number":[237],"number_text":"੨੩੭।","page":368,"lines":[{"gurmukhi":"ਕੋਕਿਲ ਕੀਰ ਕੁਰੰਗਨ ਕੇਹਰਿ ਮੈਨ ਰਹਿਯੋ ਹ੍ਵੈ ਕੈ ਮਤਵਾਰੋ।","roman":"Kokil keer kurangan kehri main rahiyo hvai kai matvaaro |","meaning_en":"","page":368},{"gurmukhi":"ਰੀਝ ਰਹੇ ਸਭ ਹੀ ਪੁਰ ਕੇ ਜਨ ਆਨਨ ਪੈ ਇਹ ਤੈ ਸਸਿ ਹਾਰੋ।","roman":"Reejh rahe sabh hee pur ke jan aanan pai ih tai sasi haaro |","meaning_en":"","page":368},{"gurmukhi":"ਅਉ ਇਹ ਕੀ ਮੁਰਲੀ ਜੁ ਬਜੈ ਤਿਹ ਊਪਰਿ ਰਾਗ ਸਭੈ ਫੁਨਿ ਵਾਰੋ।","roman":"Au ih kee murlee ju bajai tih oopri raag sabhai phuni vaaro |","meaning_en":"","page":369},{"gurmukhi":"ਨਾਰਦ ਜਾਤ ਥਕੈ ਇਹ ਤੈ ਬੰਸੁਰੀ ਜੁ ਬਜਾਵਤ ਕਾਨਰ ਕਾਰੋ। ੨੩੭।","roman":"Naarad jaat thakai ih tai bansuree ju bajaavat kaanar kaaro | 237 |","meaning_en":"","page":369}]},{"type":"verse","number":[238],"number_text":"੨੩੮।","page":369,"lines":[{"gurmukhi":"ਲੋਚਨ ਹੈ ਮ੍ਰਿਗ ਕੇ ਕਟਿ ਕੇਹਰਿ ਨਾਕ ਕਿਧੋ ਸੁਕ ਸੋ ਤਿਹ ਕੋ ਹੈ।","roman":"Lochan hai mrig ke kati kehri naak kidho suk so tih ko hai |","meaning_en":"","page":369},{"gurmukhi":"ਗ੍ਰੀਵ ਕਪੋਤ ਸੀ ਹੈ ਤਿਹ ਕੀ ਅਧਰਾ ਪੀਆ ਸੇ ਹਰਿ ਮੂਰਤਿ ਜੋ ਹੈ।","roman":"Greev kapot see hai tih kee adhraa peeaa se hari moorti jo hai |","meaning_en":"","page":369},{"gurmukhi":"ਕੋਕਿਲ ਅਉ ਪਿਕ ਸੇ ਬਚਨਾਮ੍ਰਿਤ ਸ੍ਯਾਮ ਕਹੈ ਕਬਿ ਸੁੰਦਰ ਸੋਹੈ।","roman":"Kokil au pik se bachnaamrit syaam kahai kabi sundar sohai |","meaning_en":"","page":369},{"gurmukhi":"ਪੈ ਇਹ ਤੇ ਲਜ ਕੈ ਅਬ ਬੋਲਤ ਮੂਰਤਿ ਲੈਨ ਕਰੈ ਖਗ ਰੋਹੈ। ੨੩੮।","roman":"Pai ih te laj kai ab bolat moorti lain karai khag rohai | 238 |","meaning_en":"","page":369}]},{"type":"verse","number":[239],"number_text":"੨੩੯।","page":369,"lines":[{"gurmukhi":"ਫੂਲ ਗੁਲਾਬ ਨ ਲੇਤ ਹੈ ਤਾਬ ਸਹਾਬ ਕੋ ਆਬ ਹ੍ਵੈ ਦੇਖਿ ਖਿਸਾਨੋ।","roman":"Phool gulaab na let hai taab sahaab ko aab hvai dekhi khisaano |","meaning_en":"","page":369},{"gurmukhi":"ਪੈ ਕਮਲਾ ਦਲ ਨਰਗਸ ਕੋ ਗੁਲ ਲਜਤ ਹ੍ਵੈ ਫੁਨਿ ਦੇਖਤ ਤਾਨੋ।","roman":"Pai kamlaa dal nargas ko gul lajat hvai phuni dekhat taano |","meaning_en":"","page":369},{"gurmukhi":"ਸ੍ਯਾਮ ਕਿਧੋ ਅਪੁਨੇ ਮਨ ਮੈ ਬਰਤਾ ਗਨਿ ਕੈ ਕਬਿਤਾ ਇਹ ਠਾਨੋ।","roman":"Syaam kidho apune man mai bartaa gani kai kabitaa ih thaano |","meaning_en":"","page":369},{"gurmukhi":"ਦੇਖਨ ਕੋ ਇਨ ਕੇ ਸਮ ਪੂਰਬ ਪਛਮ ਡੋਲੈ ਲਹੈ ਨਹਿ ਆਨੋ। ੨੩੯।","roman":"Dekhan ko in ke sam poorab pachham dolai lahai nahi aano | 239 |","meaning_en":"","page":369}]},{"type":"verse","number":[240],"number_text":"੨੪੦।","page":369,"lines":[{"gurmukhi":"ਮੰਘਰ ਮੈ ਸਭ ਹੀ ਗੁਪੀਆ ਮਿਲਿ ਪੂਜਤ ਚੰਡਿ ਪਤੇ ਹਰਿ ਕਾਜੈ।","roman":"Manghar mai sabh hee gupeeaa mili poojat chandi pate hari kaajai |","meaning_en":"","page":369},{"gurmukhi":"ਪ੍ਰਾਤ ਸਮੇ ਜਮੁਨਾ ਮਧਿ ਨ੍ਹਾਵਤ ਦੇਖਿ ਤਿਨੈ ਜਲਜੰ ਮੁਖ ਲਾਜੈ।","roman":"Praat same jamunaa madhi nhaavat dekhi tinai jaljan mukh laajai |","meaning_en":"","page":369},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਿਲਾਵਲ ਮੈ ਜੁਰਿ ਬਾਹਨਿ ਸ੍ਯਾਮ ਕਥਾ ਇਹ ਸਾਜੈ।","roman":"Gaavat geet bilaaval mai juri baahni syaam kathaa ih saajai |","meaning_en":"","page":369},{"gurmukhi":"ਅੰਗਿ ਅਨੰਗ ਬਢਿਓ ਤਿਨ ਕੇ ਪਿਖ ਕੈ ਜਿਹ ਲਾਜ ਕੋ ਭਾਜਨ ਭਾਜੈ।੨੪੦।","roman":"Angi anang badhio tin ke pikh kai jih laaj ko bhaajan bhaajai | 240 |","meaning_en":"","page":369}]},{"type":"verse","number":[241],"number_text":"੨੪੧।","page":369,"lines":[{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਬਿਲਾਵਲ ਮੈ ਸਭ ਹੀ ਮਿਲਿ ਗੋਪਿਨ ਉਜਲ ਕਾਰੀ।","roman":"Gaavat geet bilaaval mai sabh hee mili gopin ujal kaaree |","meaning_en":"","page":369},{"gurmukhi":"ਕਾਨਰ ਕੋ ਭਰਤਾ ਕਰਬੇ ਕਹੁ ਬਾਛਤ ਹੈ ਪਤਲੀ ਅਰੁ ਭਾਰੀ।","roman":"Kaanar ko bhartaa karbe kahu baachhat hai patlee aru bhaaree |","meaning_en":"","page":369},{"gurmukhi":"ਸ੍ਯਾਮ ਕਰੈ ਤਿਨ ਕੇ ਮੁਖ ਕੌ ਪਿਖਿ ਜੋਤਿ ਕਲਾ ਸਸਿ ਕੀ ਫੁਨਿ ਹਾਰੀ।","roman":"Syaam karai tin ke mukh kau pikhi joti kalaa sasi kee phuni haaree |","meaning_en":"","page":369},{"gurmukhi":"ਨ੍ਹਾਵਤ ਹੈ ਜਮੁਨਾ ਜਲ ਮੈ ਜਨੁ ਫੂਲ ਰਹੀ ਗ੍ਰਿਹ ਮੈ ਫੁਲਵਾਰੀ। ੨੪੧।","roman":"Nhaavat hai jamunaa jal mai janu phool rahee grih mai phulvaaree | 241 |","meaning_en":"","page":369}]},{"type":"verse","number":[242],"number_text":"੨੪੨।","page":369,"lines":[{"gurmukhi":"ਨ੍ਹਾਵਤ ਹੈ ਗੁਪੀਆ ਜਲ ਮੈ ਤਿਨ ਕੇ ਮਨ ਮੈ ਫੁਨਿ ਹਉਲ ਨ ਕੋ।","roman":"Nhaavat hai gupeeaa jal mai tin ke man mai phuni haul na ko |","meaning_en":"","page":369},{"gurmukhi":"ਗੁਨ ਗਾਵਤ ਤਾਲ ਬਜਾਵਤ ਹੈ ਤਿਹ ਜਾਇ ਕਿਧੌ ਇਕ ਠਉਲਨ ਕੋ।","roman":"Gun gaavat taal bajaavat hai tih jaai kidhau ik thaulan ko |","meaning_en":"","page":369},{"gurmukhi":"ਮੁਖਿ ਤੇ ਉਚਰੈ ਇਹ ਭਾਤਿ ਸਭੈ ਇਤਨੋ ਸੁਖ ਨ ਹਰਿ ਧਉਲਨ ਕੋ।","roman":"Mukhi te uchrai ih bhaati sabhai itno sukh na hari dhaulan ko |","meaning_en":"","page":369},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਬਿਰਾਜਤ ਹੈ ਅਤਿ ਸਹੀ ਇਕ ਬਨਿਓ ਸਰ ਸੁੰਦਰ ਕਉਲਨ ਕੋ।੨੪੨।","roman":"Kabi syaam biraajat hai ati sahee ik banio sar sundar kaulan ko | 242 |","meaning_en":"","page":369}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"","page":369},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":369},{"type":"verse","number":[243],"number_text":"੨੪੩।","page":369,"lines":[{"gurmukhi":"ਲੈ ਅਪੁਨੇ ਕਰ ਜੋ ਮਿਟੀਆ ਤਿਹ ਥਾਪ ਕਹੈ ਮੁਖ ਤੇ ਜੁ ਭਵਾਨੀ।","roman":"Lai apune kar jo miteeaa tih thaap kahai mukh te ju bhavaanee |","meaning_en":"","page":369},{"gurmukhi":"ਪਾਇ ਪਰੈ ਤਿਹ ਕੇ ਹਿਤ ਸੋ ਕਰਿ ਕੋਟਿ ਪ੍ਰਨਾਮੁ ਕਹੈ ਇਹ ਬਾਨੀ।","roman":"Paai parai tih ke hit so kari koti pranaamu kahai ih baanee |","meaning_en":"","page":369},{"gurmukhi":"ਪੂਜਤ ਹੈ ਇਹ ਤੇ ਹਮ ਤੋ ਤੁਮ ਦੇਹੁ ਵਹੈ ਜੀਅ ਮੈ ਹਮ ਠਾਨੀ।","roman":"Poojat hai ih te ham to tum dehu vahai jeea mai ham thaanee |","meaning_en":"","page":370},{"gurmukhi":"ਹ੍ਵੈ ਹਮਰੋ ਭਰਤਾ ਹਰਿ ਜੀ ਮੁਖਿ ਸੁੰਦਰਿ ਹੈ ਜਿਹ ਕੋ ਸਸਿ ਸਾਨੀ। ੨੪੩।","roman":"Hvai hamro bhartaa hari jee mukhi sundri hai jih ko sasi saanee | 243 |","meaning_en":"","page":370}]},{"type":"verse","number":[244],"number_text":"੨੪੪।","page":370,"lines":[{"gurmukhi":"ਭਾਲਿ ਲਗਾਵਤ ਕੇਸਰ ਅਛਤ ਚੰਦਨ ਲਾਵਤ ਹੈ ਸਿਤ ਕੈ।","roman":"Bhaali lagaavat kesar achhat chandan laavat hai sit kai |","meaning_en":"","page":370},{"gurmukhi":"ਫੁਨਿ ਡਾਰਤ ਫੂਲ ਉਡਾਵਤ ਹੈ ਮਖੀਆ ਤਿਹ ਕੀ ਅਤਿ ਹੀ ਹਿਤ ਕੈ।","roman":"Phuni daarat phool udaavat hai makheeaa tih kee ati hee hit kai |","meaning_en":"","page":370},{"gurmukhi":"ਪਟ ਧੂਪ ਪਚਾਮ੍ਰਿਤ ਦਛਨਾ ਪਾਨ ਪ੍ਰਦਛਨਾ ਦੇਤ ਮਹਾ ਚਿਤ ਕੈ।","roman":"Pat dhoop pachaamrit dachhnaa paan pradachhnaa det mahaa chit kai |","meaning_en":"","page":370},{"gurmukhi":"ਬਰਬੇ ਕਹੁ ਕਾਨ੍ਹ ਉਪਾਉ ਕਰੈ ਮਿਤ ਹੋ ਸੋਊ ਤਾਤ ਕਿਧੌ ਕਿਤ ਕੈ। ੨੪੪।","roman":"Barbe kahu kaanh upaau karai mit ho so'oo taat kidhau kit kai | 244 |","meaning_en":"","page":370}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"","page":370},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":370},{"type":"verse","number":[245],"number_text":"੨੪੫।","page":370,"lines":[{"gurmukhi":"ਦੈਤਨ ਸੰਘਾਰਨੀ ਪਤਿਤ ਲੋਕ ਤਾਰਨੀ ਸੁ ਸੰਕਟ ਨਿਵਾਰਨੀ ਕਿ ਐਸੀ ਤੂੰ ਸਕਤਿ ਹੈ।","roman":"Daitan sanghaarnee patit lok taarnee su sankat nivaarnee ki aisee toon sakti hai |","meaning_en":"","page":370},{"gurmukhi":"ਬੇਦਨ ਉਧਾਰਨੀ ਸੁਰੇਂਦ੍ਰ ਰਾਜ ਕਾਰਨੀ ਪੈ ਗਉਰਜਾ ਕੀ ਜਾਗੈ ਜੋਤਿ ਅਉਰ ਜਾਨ ਕਤ ਹੈ।","roman":"Bedan udhaarnee surendr raaj kaarnee pai gaurjaa kee jaagai joti aur jaan kat hai |","meaning_en":"","page":370},{"gurmukhi":"ਧੂਅ ਮੈ ਨ ਧਰਾ ਮੈ ਨ ਧਿਆਨ ਧਾਰੀ ਮੈ ਪੈ ਕਛੂ ਜੈਸੇ ਤੇਰੇ ਜੋਤਿ ਬੀਚ ਆਨਨ ਛਕਤਿ ਹੈ।","roman":"Dhooa mai na dharaa mai na dhiaan dhaaree mai pai kachhoo jaise tere joti beech aanan chhakti hai |","meaning_en":"","page":370},{"gurmukhi":"ਦਿਨਸ ਦਿਨੇਸ ਮੈ ਦਿਵਾਨ ਮੈ ਸੁਰੇਸ ਮੈ ਸੁਪਤ ਮਹੇਸ ਜੋਤਿ ਤੇਰੀ ਐ ਜਗਤਿ ਹੈ। ੨੪੫।","roman":"Dinas dines mai divaan mai sures mai supat mahes joti teree ai jagti hai | 245 |","meaning_en":"","page":370}]},{"type":"verse","number":[246],"number_text":"੨੪੬।","page":370,"lines":[{"gurmukhi":"ਬਿਨਤੀ ਕਰਤ ਸਭ ਗੋਪੀ ਕਰਿ ਜੋਰਿ ਜੋਰਿ ਸੁਨਿ ਲੇਹੁ ਬਿਨਤੀ ਹਮਾਰੀ ਇਹ ਚੰਡਿਕਾ।","roman":"Bintee karat sabh gopee kari jori jori suni lehu bintee hamaaree ih chandikaa |","meaning_en":"","page":370},{"gurmukhi":"ਸੁਰ ਤੈ ਉਬਾਰੇ ਕੋਟਿ ਪਤਿਤ ਉਧਾਰੇ ਚੰਡ ਮੁੰਡ ਮੁੰਡ ਡਾਰੇ ਸੁੰਭ ਨਿਸੁੰਭ ਕੀ ਖੰਡਿਕਾ।","roman":"Sur tai ubaare koti patit udhaare chand mund mund daare sunbh nisunbh kee khandikaa |","meaning_en":"","page":370},{"gurmukhi":"ਦੀਜੈ ਮਾਗਿਯੋ ਦਾਨ ਹ੍ਵੈ ਪ੍ਰਤਛ ਕਹੈ ਮੇਰੀ ਮਾਈ ਪੂਜੇ ਹਮ ਤੁਮੈ ਨਾਹੀ ਪੁਜੈ ਸੁਤ ਗੰਡਕਾ।","roman":"Deejai maagiyo daan hvai pratachh kahai meree maaee pooje ham tumai naahee pujai sut gandkaa |","meaning_en":"","page":370},{"gurmukhi":"ਹ੍ਵੈ ਕਰਿ ਪ੍ਰਸੰਨ੍ਯ ਤਾ ਕੋ ਕਹਿਓ ਸੀਘ੍ਰ ਮਾਨ ਦੀਨੋ ਵਹੈ ਬਰ ਦਾਨ ਫੁਨਿ ਰਾਨਿਨ ਕੀਮੰਡਿਕਾ।੨੪੬।","roman":"Hvai kari prasanny taa ko kahio seeghr maan deeno vahai bar daan phuni raanin keemandikaa | 246 |","meaning_en":"","page":370}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਜੀ ਬਾਚ ਗੋਪਿਨ ਸੋ","gurmukhi":"ਦੇਵੀ ਜੀ ਬਾਚ ਗੋਪਿਨ ਸੋ","roman":"Devee jee baach gopin so","meaning_en":"","page":370},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":370},{"type":"verse","number":[247],"number_text":"੨੪੭।","page":370,"lines":[{"gurmukhi":"ਹ੍ਵੈ ਭਰਤਾ ਅਬ ਸੋ ਤੁਮਰੋ ਹਰਿ ਦਾਨ ਇਹੇ ਦੁਰਗਾ ਤਿਨ ਦੀਨਾ।","roman":"Hvai bhartaa ab so tumro hari daan ihe durgaa tin deenaa |","meaning_en":"","page":370},{"gurmukhi":"ਸੋ ਧੁਨਿ ਸ੍ਰਉਨਨ ਮੈ ਸੁਨ ਕੈ ਤਿਨ ਕੋਟਿ ਪ੍ਰਨਾਮ ਤਬੈ ਉਠਿ ਕੀਨਾ।","roman":"So dhuni sraunan mai sun kai tin koti pranaam tabai uthi keenaa |","meaning_en":"","page":370},{"gurmukhi":"ਤਾ ਛਬਿ ਕੋ ਜਸੁ ਉਚ ਮਹਾ ਕਬਿ ਨੇ ਅਪਨੇ ਮਨ ਮੈ ਫੁਨਿ ਚੀਨਾ।","roman":"Taa chhabi ko jasu uch mahaa kabi ne apne man mai phuni cheenaa |","meaning_en":"","page":370},{"gurmukhi":"ਹੈ ਇਨ ਕੋ ਮਨੁ ਕਾਨਰ ਮੈ ਅਉ ਜੋ ਪੈ ਰਸ ਕਾਨਰ ਕੇ ਸੰਗਿ ਭੀਨਾ। ੨੪੭।","roman":"Hai in ko manu kaanar mai au jo pai ras kaanar ke sangi bheenaa | 247 |","meaning_en":"","page":370}]},{"type":"verse","number":[248],"number_text":"੨੪੮।","page":371,"lines":[{"gurmukhi":"ਪਾਇ ਪਰੀ ਤਿਹ ਕੇ ਤਬ ਹੀ ਸਭ ਭਾਤਿ ਕਰੀ ਬਹੁ ਤਾਹਿ ਬਡਾਈ।","roman":"Paai paree tih ke tab hee sabh bhaati karee bahu taahi badaaee |","meaning_en":"","page":371},{"gurmukhi":"ਹੈ ਜਗ ਕੀ ਕਰਤਾ ਹਰਤਾ ਦੁਖ ਹੈ ਸਭ ਤੂ ਗਨ ਗੰਧ੍ਰਬ ਮਾਈ।","roman":"Hai jag kee kartaa hartaa dukh hai sabh too gan gandhrab maaee |","meaning_en":"","page":371},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਅਤਿ ਹੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਭਾਖਿ ਸੁਨਾਈ।","roman":"Taa chhabi kee ati hee upmaa kabi ne mukh te im bhaakhi sunaaee |","meaning_en":"","page":371},{"gurmukhi":"ਲਾਲ ਭਈ ਤਬ ਹੀ ਗੁਪੀਆ ਫੁਨਿ ਬਾਤ ਜਬੈ ਮਨ ਬਾਛਤ ਪਾਈ। ੨੪੮।","roman":"Laal bhaee tab hee gupeeaa phuni baat jabai man baachhat paaee | 248 |","meaning_en":"","page":371}]},{"type":"verse","number":[249],"number_text":"੨੪੯।","page":371,"lines":[{"gurmukhi":"ਲੈ ਬਰਦਾਨ ਸਭੈ ਗੁਪੀਆ ਅਤਿ ਆਨੰਦ ਕੈ ਮਨਿ ਡੇਰਨ ਆਈ।","roman":"Lai bardaan sabhai gupeeaa ati aanand kai mani deran aaee |","meaning_en":"","page":371},{"gurmukhi":"ਗਾਵਤ ਗੀਤ ਸਭੈ ਮਿਲ ਕੈ ਇਕ ਹ੍ਵੈ ਕੈ ਪ੍ਰਸੰਨ੍ਯ ਸੁ ਦੇਤ ਬਧਾਈ।","roman":"Gaavat geet sabhai mil kai ik hvai kai prasanny su det badhaaee |","meaning_en":"","page":371},{"gurmukhi":"ਪਾਤਨ ਸਾਥ ਖਰੀ ਤਿਨ ਕੀ ਉਪਮਾ ਕਬਿ ਨੇ ਮੁਖ ਤੇ ਇਮ ਗਾਈ।","roman":"Paatan saath kharee tin kee upmaa kabi ne mukh te im gaaee |","meaning_en":"","page":371},{"gurmukhi":"ਮਾਨਹੁ ਪਾਇ ਨਿਸਾਪਤਿ ਕੋ ਸਰ ਮਧਿ ਖਿਰੀ ਕਵੀਆ ਧੁਰ ਤਾਈ। ੨੪੯।","roman":"Maanhu paai nisaapti ko sar madhi khiree kaveeaa dhur taaee | 249 |","meaning_en":"","page":371}]},{"type":"verse","number":[250],"number_text":"੨੫੦।","page":371,"lines":[{"gurmukhi":"ਪ੍ਰਾਤ ਭਏ ਜਮਨਾ ਜਲ ਮੈ ਮਿਲਿ ਧਾਇ ਗਈ ਸਭ ਹੀ ਗੁਪੀਆ।","roman":"Praat bhae jamnaa jal mai mili dhaai gaee sabh hee gupeeaa |","meaning_en":"","page":371},{"gurmukhi":"ਮਿਲਿ ਗਾਵਤ ਗੀਤ ਚਲੀ ਤਿਹ ਜਾ ਕਰਿ ਆਨੰਦ ਭਾਮਿਨ ਮੈ ਕੁਪੀਆ।","roman":"Mili gaavat geet chalee tih jaa kari aanand bhaamin mai kupeeaa |","meaning_en":"","page":371},{"gurmukhi":"ਤਬ ਹੀ ਫੁਨਿ ਕਾਨ੍ਹ ਚਲੇ ਤਿਹ ਜਾ ਜਮੁਨਾ ਜਲ ਕੋ ਫੁਨਿ ਜਾ ਜੁ ਪੀਆ।","roman":"Tab hee phuni kaanh chale tih jaa jamunaa jal ko phuni jaa ju peeaa |","meaning_en":"","page":371},{"gurmukhi":"ਸੋਊ ਦੇਖਿ ਤਬੈ ਭਗਵਾਨ ਕਹੇ ਨਹਿ ਬੋਲਹੁ ਰੀ ਕਰਿ ਹੋ ਚੁਪੀਆ। ੨੫੦।","roman":"So'oo dekhi tabai bhagvaan kahe nahi bolhu ree kari ho chupeeaa | 250 |","meaning_en":"","page":371}]},{"type":"heading","kind":"section_heading","name":"ਅਥ ਚੀਰ ਚਰਨ ਕਥਨੰ","gurmukhi":"ਅਥ ਚੀਰ ਚਰਨ ਕਥਨੰ","roman":"Ath cheer charan kathnan","meaning_en":"","page":371},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":371},{"type":"verse","number":[251],"number_text":"੨੫੧।","page":371,"lines":[{"gurmukhi":"ਨ੍ਹਾਵਨਿ ਲਾਗਿ ਜਬੈ ਗੁਪੀਆ ਤਬ ਲੈ ਪਟ ਕਾਨ ਚਰਿਯੋ ਤਰੁ ਊਪੈ।","roman":"Nhaavni laagi jabai gupeeaa tab lai pat kaan chariyo taru oopai |","meaning_en":"","page":371},{"gurmukhi":"ਤਉ ਮੁਸਕਯਾਨ ਲਗੀ ਮਧਿ ਆਪਨ ਕੋਇ ਪੁਕਾਰ ਕਰੇ ਹਰਿ ਜੂ ਪੈ।","roman":"Tau musakyaan lagee madhi aapan koi pukaar kare hari joo pai |","meaning_en":"","page":371},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਛਲ ਸੋ ਤੁਮ ਸੋ ਠਗ ਨਾਹਿ ਕਿਧੋ ਕੋਊ ਭੂ ਪੈ।","roman":"Cheer hare hamre chhal so tum so thag naahi kidho ko'oo bhoo pai |","meaning_en":"","page":371},{"gurmukhi":"ਹਾਥਨ ਸਾਥ ਸੁ ਸਾਰੀ ਹਰੀ ਦ੍ਰਿਗ ਸਾਥ ਹਰੋ ਹਮਰੋ ਤੁਮ ਰੂਪੈ। ੨੫੧।","roman":"Haathan saath su saaree haree drig saath haro hamro tum roopai | 251 |","meaning_en":"","page":371}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ ਜੂ ਸੋ","roman":"Gopee baach kaan joo so","meaning_en":"","page":371},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":371},{"type":"verse","number":[252],"number_text":"੨੫੨।","page":371,"lines":[{"gurmukhi":"ਸ੍ਯਾਮ ਕਹਿਯੋ ਮੁਖ ਤੇ ਗੁਪੀਆ ਇਹ ਕਾਨ੍ਹ ਸਿਖੇ ਤੁਮ ਬਾਤ ਭਲੀ ਹੈ।","roman":"Syaam kahiyo mukh te gupeeaa ih kaanh sikhe tum baat bhalee hai |","meaning_en":"","page":371},{"gurmukhi":"ਨੰਦ ਕੀ ਓਰ ਪਿਖੋ ਤੁਮ ਹੂੰ ਦਿਖੋ ਭ੍ਰਾਤ ਕੀ ਓਰ ਕਿ ਨਾਮ ਹਲੀ ਹੈ।","roman":"Nand kee or pikho tum hoon dikho bhraat kee or ki naam halee hai |","meaning_en":"","page":371},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਛਲ ਸੋ ਸੁਨਿ ਮਾਰਿ ਡਰੈ ਤੁਹਿ ਕੰਸ ਬਲੀ ਹੈ।","roman":"Cheer hare hamre chhal so suni maari darai tuhi kans balee hai |","meaning_en":"","page":371},{"gurmukhi":"ਕੋ ਮਰ ਹੈ ਹਮ ਕੋ ਤੁਮਰੋ ਨ੍ਰਿਪ ਤੋਰ ਡਰੈ ਜਿਮ ਕਉਲ ਕਲੀ ਹੈ। ੨੫੨।","roman":"Ko mar hai ham ko tumro nrip tor darai jim kaul kalee hai | 252 |","meaning_en":"","page":371}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਗੋਪੀ ਸੋ","roman":"Kaanh baach gopee so","meaning_en":"","page":372},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":372},{"type":"verse","number":[253],"number_text":"੨੫੩।","page":372,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਤਿਨ ਕੋ ਇਹ ਬਾਤ ਨ ਦਿਓ ਪਟ ਹਉ ਨਿਕਰਿਯੋ ਬਿਨੁ ਤੋ ਕੋ।","roman":"Kaanh kahee tin ko ih baat na dio pat hau nikriyo binu to ko |","meaning_en":"","page":372},{"gurmukhi":"ਕਿਉ ਜਲ ਬੀਚ ਰਹੀ ਛਪ ਕੈ ਤਨ ਕਾਹਿ ਕਟਾਵਤ ਹੋ ਪਹਿ ਜੋਕੋ।","roman":"Kiu jal beech rahee chhap kai tan kaahi kataavat ho pahi joko |","meaning_en":"","page":372},{"gurmukhi":"ਨਾਮ ਬਤਾਵਤ ਹੋ ਨ੍ਰਿਪ ਕੋ ਤਿਹ ਕੋ ਫੁਨਿ ਨਾਹਿ ਕਛੂ ਡਰੁ ਮੋਕੋ।","roman":"Naam bataavat ho nrip ko tih ko phuni naahi kachhoo daru moko |","meaning_en":"","page":372},{"gurmukhi":"ਕੇਸਨ ਤੇ ਗਹਿ ਕੈ ਤਪ ਕੀ ਅਗਨੀ ਮਧਿ ਈਧਨ ਜਿਉ ਉਹਿ ਝੋਕੋ। ੨੫੩।","roman":"Kesan te gahi kai tap kee agnee madhi eedhan jiu uhi jhoko | 253 |","meaning_en":"","page":372}]},{"type":"verse","number":[254],"number_text":"੨੫੪।","page":372,"lines":[{"gurmukhi":"ਰੂਖਿ ਚਰੇ ਹਰਿ ਜੀ ਰਿਝ ਕੈ ਮੁਖ ਤੇ ਜਬ ਬਾਤ ਕਹੀ ਇਹ ਤਾ ਸੋ।","roman":"Rookhi chare hari jee rijh kai mukh te jab baat kahee ih taa so |","meaning_en":"","page":372},{"gurmukhi":"ਤਉ ਰਿਸਿ ਬਾਤ ਕਹੀ ਉਨ ਹੂੰ ਇਹ ਜਾਇ ਕਹੈ ਤੁਹਿ ਮਾਤ ਪਿਤਾ ਸੋ।","roman":"Tau risi baat kahee un hoon ih jaai kahai tuhi maat pitaa so |","meaning_en":"","page":372},{"gurmukhi":"ਜਾਇ ਕਹੋ ਇਹ ਕਾਨ੍ਹ ਕਹੀ ਮਨ ਹੈ ਤੁਮਰੋ ਕਹਬੇ ਕਹੁ ਜਾ ਸੋ।","roman":"Jaai kaho ih kaanh kahee man hai tumro kahbe kahu jaa so |","meaning_en":"","page":372},{"gurmukhi":"ਜੋ ਸੁਨਿ ਕੋਊ ਕਹੈ ਹਮ ਕੋ ਇਹ ਤੋ ਹਮ ਹੂੰ ਸਮਝੈ ਫੁਨਿ ਵਾ ਸੋ। ੨੫੪।","roman":"Jo suni ko'oo kahai ham ko ih to ham hoon samjhai phuni vaa so | 254 |","meaning_en":"","page":372}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"","page":372},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":372},{"type":"verse","number":[255],"number_text":"੨੫੫।","page":372,"lines":[{"gurmukhi":"ਦੇਉ ਬਿਨਾ ਨਿਕਰੈ ਨਹਿ ਚੀਰ ਕਹਿਯੋ ਹਸਿ ਕਾਨ੍ਹ ਸੁਨੋ ਤੁਮ ਪਿਆਰੀ।","roman":"Deu binaa nikrai nahi cheer kahiyo hasi kaanh suno tum piaaree |","meaning_en":"","page":372},{"gurmukhi":"ਸੀਤ ਸਹੋ ਜਲ ਮੈ ਤੁਮ ਨਾਹਕ ਬਾਹਰਿ ਆਵਹੋ ਗੋਰੀ ਅਉ ਕਾਰੀ।","roman":"Seet saho jal mai tum naahak baahri aavho goree au kaaree |","meaning_en":"","page":372},{"gurmukhi":"ਦੇ ਅਪੁਨੇ ਅਗੂਆ ਪਿਛੂਆ ਕਰ ਬਾਰਿ ਤਜੋ ਪਤਲੀ ਅਰੁ ਭਾਰੀ।","roman":"De apune agooaa pichhooaa kar baari tajo patlee aru bhaaree |","meaning_en":"","page":372},{"gurmukhi":"ਯੌ ਨਹਿ ਦੇਉ ਕਹਿਓ ਹਰਿ ਜੀ ਤਸਲੀਮ ਕਰੋ ਕਰ ਜੋਰਿ ਹਮਾਰੀ। ੨੫੫।","roman":"Yau nahi deu kahio hari jee tasleem karo kar jori hamaaree | 255 |","meaning_en":"","page":372}]},{"type":"verse","number":[256],"number_text":"੨੫੬।","page":372,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਹਰਿ ਜੀ ਤਿਨ ਸੋ ਰਿਝ ਕੈ ਇਹ ਬਾਤ ਸੁਨੋ ਤੁਮ ਮੇਰੀ।","roman":"Pheri kahee hari jee tin so rijh kai ih baat suno tum meree |","meaning_en":"","page":372},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮਰੋ ਕਰ ਲਾਜ ਕੀ ਕਾਟਿ ਸਭੈ ਤੁਮ ਬੇਰੀ।","roman":"Jori pranaam karo hamro kar laaj kee kaati sabhai tum beree |","meaning_en":"","page":372},{"gurmukhi":"ਬਾਰ ਹੀ ਬਾਰ ਕਹਿਯੋ ਤੁਮ ਸੋ ਮੁਹਿ ਮਾਨਹੁ ਸੀਘ੍ਰ ਕਿਧੋ ਇਹ ਹੇ ਰੀ।","roman":"Baar hee baar kahiyo tum so muhi maanhu seeghr kidho ih he ree |","meaning_en":"","page":372},{"gurmukhi":"ਨਾਤੁਰ ਜਾਇ ਕਹੋ ਸਭ ਹੀ ਪਹਿ ਸਉਹ ਲਗੈ ਫੁਨਿ ਠਾਕੁਰ ਕੇਰੀ। ੨੫੬।","roman":"Naatur jaai kaho sabh hee pahi sauh lagai phuni thaakur keree | 256 |","meaning_en":"","page":372}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"","page":372},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":372},{"type":"verse","number":[257],"number_text":"੨੫੭।","page":372,"lines":[{"gurmukhi":"ਜੋ ਤੁਮ ਜਾਇ ਕਹੋ ਤਿਨ ਹੀ ਪਹਿ ਤੋ ਹਮ ਬਾਤ ਬਨਾਵਹਿ ਐਸੇ।","roman":"Jo tum jaai kaho tin hee pahi to ham baat banaavhi aise |","meaning_en":"","page":372},{"gurmukhi":"ਚੀਰ ਹਰੇ ਹਮਰੇ ਹਰਿ ਜੀ ਦਈ ਬਾਰਿ ਤੇ ਨਿਆਰੀ ਕਢੈ ਹਮ ਕੈਸੇ।","roman":"Cheer hare hamre hari jee daee baari te niaaree kadhai ham kaise |","meaning_en":"","page":372},{"gurmukhi":"ਭੇਦ ਕਹੈ ਸਭ ਹੀ ਜਸੁਧਾ ਪਹਿ ਤੋਹਿ ਕਰੈ ਸਰਮਿੰਦਤ ਵੈਸੇ।","roman":"Bhed kahai sabh hee jasudhaa pahi tohi karai sarmindat vaise |","meaning_en":"","page":372},{"gurmukhi":"ਜਿਉ ਨਰ ਕੋ ਗਹਿ ਕੈ ਤਿਰੀਯਾ ਹੂੰ ਸੁ ਮਾਰਤ ਲਾਤਨ ਮੂਕਨ ਜੈਸੇ। ੨੫੭।","roman":"Jiu nar ko gahi kai tireeyaa hoon su maarat laatan mookan jaise | 257 |","meaning_en":"","page":372}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"","page":373},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":373},{"type":"verse","number":[258],"number_text":"੨੫੮।","page":373,"lines":[{"gurmukhi":"ਬਾਤ ਕਹੀ ਤਬ ਇਹ ਹਰੀ ਕਾਹਿ ਬੰਧਾਵਤ ਮੋਹਿ।","roman":"Baat kahee tab ih haree kaahi bandhaavat mohi |","meaning_en":"","page":373},{"gurmukhi":"ਨਮਸਕਾਰ ਜੋ ਨ ਕਰੋ ਮੋਹਿ ਦੁਹਾਈ ਤੋਹਿ। ੨੫੮।","roman":"Namaskaar jo na karo mohi duhaaee tohi | 258 |","meaning_en":"","page":373}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":373},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":373},{"type":"verse","number":[259],"number_text":"੨੫੯।","page":373,"lines":[{"gurmukhi":"ਕਾਹਿ ਖਿਝਾਵਤ ਹੋ ਹਮ ਕੋ ਅਰੁ ਦੇਤ ਕਹਾ ਜਦੁਰਾਇ ਦੁਹਾਈ।","roman":"Kaahi khijhaavat ho ham ko aru det kahaa jaduraai duhaaee |","meaning_en":"","page":373},{"gurmukhi":"ਜਾ ਬਿਧਿ ਕਾਰਨ ਬਾਤ ਬਨਾਵਤ ਸੋ ਬਿਧਿ ਹਮ ਹੂੰ ਲਖਿ ਪਾਈ।","roman":"Jaa bidhi kaaran baat banaavat so bidhi ham hoon lakhi paaee |","meaning_en":"","page":373},{"gurmukhi":"ਭੇਦ ਕਰੋ ਹਮ ਸੋ ਤੁਮ ਨਾਹਕ ਬਾਤ ਇਹੈ ਮਨ ਮੈ ਤੁਹਿ ਆਈ।","roman":"Bhed karo ham so tum naahak baat ihai man mai tuhi aaee |","meaning_en":"","page":373},{"gurmukhi":"ਸਉਹ ਲਗੈ ਹਮ ਠਾਕੁਰ ਕੀ ਜੁ ਰਹੈ ਤੁਮਰੀ ਬਿਨੁ ਮਾਤ ਸੁਨਾਈ। ੨੫੯।","roman":"Sauh lagai ham thaakur kee ju rahai tumree binu maat sunaaee | 259 |","meaning_en":"","page":373}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ ਗੁਪੀਆ ਸੋ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ ਗੁਪੀਆ ਸੋ","roman":"Kaanh baach gupeeaa so","meaning_en":"","page":373},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":373},{"type":"verse","number":[260],"number_text":"੨੬੦।","page":373,"lines":[{"gurmukhi":"ਮਾ ਸੁਨਿ ਹੈ ਤਬ ਕਾ ਕਰਿ ਹੈ ਹਮਰੋ ਸੁਨਿ ਲੇਹੁ ਸਭੈ ਬ੍ਰਿਜ ਨਾਰੀ।","roman":"Maa suni hai tab kaa kari hai hamro suni lehu sabhai brij naaree |","meaning_en":"","page":373},{"gurmukhi":"ਬਾਤ ਕਹੀ ਤੁਮ ਮੂੜਨ ਕੀ ਹਮ ਜਾਨਤ ਹੈ ਤੁਮ ਹੋ ਸਭ ਬਾਰੀ।","roman":"Baat kahee tum mooran kee ham jaanat hai tum ho sabh baaree |","meaning_en":"","page":373},{"gurmukhi":"ਸੀਖਤ ਹੋ ਰਸ ਰੀਤਿ ਅਬੈ ਇਹ ਕਾਨ੍ਹ ਕਹੀ ਤੁਮ ਹੋ ਮੁਹਿ ਪਿਆਰੀ।","roman":"Seekhat ho ras reeti abai ih kaanh kahee tum ho muhi piaaree |","meaning_en":"","page":373},{"gurmukhi":"ਖੇਲਨ ਕਾਰਨ ਕੋ ਹਮ ਹੂੰ ਜੁ ਹਰੀ ਛਲ ਕੈ ਤੁਮ ਸੁੰਦਰ ਸਾਰੀ। ੨੬੦।","roman":"Khelan kaaran ko ham hoon ju haree chhal kai tum sundar saaree | 260 |","meaning_en":"","page":373}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":373},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":373},{"type":"verse","number":[261],"number_text":"੨੬੧।","page":373,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਇਮ ਗੋਪਿਨ ਬਾਤ ਇਸੀ ਮਨੁ ਏ ਪਟ ਦੈਹੋ।","roman":"Pheri kahee mukh te im gopin baat isee manu e pat daiho |","meaning_en":"","page":373},{"gurmukhi":"ਸਉਹ ਕਰੋ ਮੁਸਲੀਧਰ ਕੀ ਜਸੁਧਾ ਨੰਦ ਕੀ ਹਮ ਕੋ ਡਰ ਕੈਹੋ।","roman":"Sauh karo musleedhar kee jasudhaa nand kee ham ko dar kaiho |","meaning_en":"","page":373},{"gurmukhi":"ਕਾਨ੍ਹ ਬਿਚਾਰਿ ਪਿਖੋ ਮਨ ਮੈ ਇਨ ਬਾਤਨ ਤੇ ਤੁਮ ਨ ਕਿਛੁ ਪੈਹੋ।","roman":"Kaanh bichaari pikho man mai in baatan te tum na kichhu paiho |","meaning_en":"","page":373},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਜਲ ਮੈ ਹਮ ਕੋ ਇਹ ਦੇਹਿ ਅਸੀਸ ਸਭੈ ਤੁਹਿ ਜੈਹੋ। ੨੬੧।","roman":"Dehu kahiyo jal mai ham ko ih dehi asees sabhai tuhi jaiho | 261 |","meaning_en":"","page":373}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":373},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":373},{"type":"verse","number":[262],"number_text":"੨੬੨।","page":373,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਮਿਲਿ ਗੋਪਨ ਨੇਹ ਲਗੈ ਹਰਿ ਜੀ ਨਹਿ ਜੋਰੀ।","roman":"Pheri kahee mukh te mili gopan neh lagai hari jee nahi joree |","meaning_en":"","page":373},{"gurmukhi":"ਨੈਨਨ ਸਾਥ ਲਗੈ ਸੋਊ ਨੇਹੁ ਕਹੈ ਮੁਖ ਤੇ ਇਹ ਸਾਵਲ ਗੋਰੀ।","roman":"Nainan saath lagai so'oo nehu kahai mukh te ih saaval goree |","meaning_en":"","page":373},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਇਹ ਬਾਤ ਸੁਨੋ ਰਸ ਰੀਤਿ ਕਹੋ ਮਮ ਹੋਰੀ।","roman":"Kaanh kahee hasi kai ih baat suno ras reeti kaho mam horee |","meaning_en":"","page":373},{"gurmukhi":"ਆਖਨ ਸਾਥ ਲਗੈ ਟਕਵਾ ਫੁਨਿ ਹਾਥਨ ਸਾਥ ਲਗੈ ਸੁਭ ਸੋਰੀ। ੨੬੨।","roman":"Aakhan saath lagai takvaa phuni haathan saath lagai subh soree | 262 |","meaning_en":"","page":373}]},{"type":"verse","number":[263],"number_text":"੨੬੩।","page":374,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖਿ ਤੇ ਗੁਪੀਆ ਹਮਰੇ ਪਟ ਦੇਹੁ ਕਹਿਯੋ ਨੰਦ ਲਾਲਾ।","roman":"Pheri kahee mukhi te gupeeaa hamre pat dehu kahiyo nand laalaa |","meaning_en":"","page":374},{"gurmukhi":"ਫੇਰਿ ਇਸਨਾਨ ਕਰੈ ਨ ਇਹਾ ਕਹਿ ਹੈ ਹਮਿ ਲੋਗਨ ਆਛਨ ਬਾਲਾ।","roman":"Pheri isnaan karai na ihaa kahi hai hami logan aachhan baalaa |","meaning_en":"","page":374},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਬਾਹਰ ਹ੍ਵੈ ਜਲ ਤੇ ਤਤਕਾਲਾ।","roman":"Jori pranaam karo ham ko kar baahar hvai jal te tatkaalaa |","meaning_en":"","page":374},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਮੁਖਿ ਤੈ ਕਰਿ ਹੋ ਨਹੀ ਢੀਲ ਦੇਉ ਪਟ ਹਾਲਾ। ੨੬੩।","roman":"Kaanh kahee hasi kai mukhi tai kari ho nahee dheel deu pat haalaa | 263 |","meaning_en":"","page":374}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":374},{"type":"verse","number":[264],"number_text":"੨੬੪।","page":374,"lines":[{"gurmukhi":"ਮੰਤ੍ਰ ਸਭਨ ਮਿਲਿ ਇਹ ਕਰਿਯੋ ਜਲ ਕੋ ਤਜਿ ਸਭ ਨਾਰਿ।","roman":"Mantr sabhan mili ih kariyo jal ko taji sabh naari |","meaning_en":"","page":374},{"gurmukhi":"ਕਾਨਰ ਕੀ ਬਿਨਤੀ ਕਰੋ ਕੀਨੋ ਇਹੈ ਬਿਚਾਰ। ੨੬੪।","roman":"Kaanar kee bintee karo keeno ihai bichaar | 264 |","meaning_en":"","page":374}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":374},{"type":"verse","number":[265],"number_text":"੨੬੫।","page":374,"lines":[{"gurmukhi":"ਦੈ ਅਗੂਆ ਪਿਛੂਆ ਅਪੁਨੇ ਕਰ ਪੈ ਸਭ ਹੀ ਜਲ ਤਿਆਗਿ ਖਰੀ ਹੈ।","roman":"Dai agooaa pichhooaa apune kar pai sabh hee jal tiaagi kharee hai |","meaning_en":"","page":374},{"gurmukhi":"ਕਾਨ ਕੇ ਪਾਇ ਪਰੀ ਬਹੁ ਬਾਰਨ ਅਉ ਬਿਨਤੀ ਬਹੁ ਭਾਤਿ ਕਰੀ ਹੈ।","roman":"Kaan ke paai paree bahu baaran au bintee bahu bhaati karee hai |","meaning_en":"","page":374},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਹਮਰੀ ਸਰ੍ਹੀਆ ਤੁਮ ਜੋ ਕਰਿ ਕੈ ਛਲ ਸਾਥ ਹਰੀ ਹੈ।","roman":"Dehu kahiyo hamree sarheeaa tum jo kari kai chhal saath haree hai |","meaning_en":"","page":374},{"gurmukhi":"ਜੇ ਕਹਿ ਹੋ ਮਨਿ ਹੈ ਹਮ ਸੋ ਅਤਿ ਹੀ ਸਭ ਸੀਤਹਿ ਸਾਥ ਠਰੀ ਹੈ। ੨੬੫।","roman":"Je kahi ho mani hai ham so ati hee sabh seethi saath tharee hai | 265 |","meaning_en":"","page":374}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਬਾਚ","roman":"Kaanh baach","meaning_en":"","page":374},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":374},{"type":"verse","number":[266],"number_text":"੨੬੬।","page":374,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਬਾਤ ਤਿਨੈ ਕਹਿ ਹੈ ਹਮ ਜੋ ਤੁਮ ਸੋ ਮਨ ਹੋ।","roman":"Kaanh kahee hasi baat tinai kahi hai ham jo tum so man ho |","meaning_en":"","page":374},{"gurmukhi":"ਸਭ ਹੀ ਮੁਖ ਚੂਮਨ ਦੇਹੁ ਕਹਿਯੋ ਚੁਮ ਹੈ ਹਮ ਹੂੰ ਤੁਮ ਹੂੰ ਗਨਿ ਹੋ।","roman":"Sabh hee mukh chooman dehu kahiyo chum hai ham hoon tum hoon gani ho |","meaning_en":"","page":374},{"gurmukhi":"ਅਰੁ ਤੋਰਨ ਦੇਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਕੁਚ ਨਾਤਰ ਹਉ ਤੁਮ ਕੋ ਹਨਿ ਹੋ।","roman":"Aru toran dehu kahiyo sabh hee kuch naatar hau tum ko hani ho |","meaning_en":"","page":374},{"gurmukhi":"ਤਬ ਹੀ ਪਟ ਦੇਉ ਸਭੈ ਤੁਮਰੇ ਇਹ ਝੂਠ ਨਹੀ ਸਤਿ ਕੈ ਜਨਿ ਹੋ। ੨੬੬।","roman":"Tab hee pat deu sabhai tumre ih jhooth nahee sati kai jani ho | 266 |","meaning_en":"","page":374}]},{"type":"verse","number":[267],"number_text":"੨੬੭।","page":374,"lines":[{"gurmukhi":"ਫੇਰਿ ਕਹੀ ਮੁਖ ਤੇ ਹਰਿ ਜੀ ਸੁਨਿ ਰੀ ਇਕ ਬਾਤ ਕਹੋ ਸੰਗ ਤੇਰੇ।","roman":"Pheri kahee mukh te hari jee suni ree ik baat kaho sang tere |","meaning_en":"","page":374},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਕਰ ਸੋ ਤੁਮ ਕਾਮ ਕਰਾ ਉਪਜੀ ਜੀਅ ਮੇਰੇ।","roman":"Jori pranaam karo kar so tum kaam karaa upjee jeea mere |","meaning_en":"","page":374},{"gurmukhi":"ਤੌ ਹਮ ਬਾਤ ਕਹੀ ਤੁਮ ਸੋ ਜਬ ਘਾਤ ਬਨੀ ਸੁਭ ਠਉਰ ਅਕੇਰੇ।","roman":"Tau ham baat kahee tum so jab ghaat banee subh thaur akere |","meaning_en":"","page":374},{"gurmukhi":"ਦਾਨ ਲਹੈ ਜੀਅ ਕੋ ਹਮ ਹੂੰ ਹਸਿ ਕਾਨ੍ਹ ਕਹੀ ਤੁਮਰੋ ਤਨ ਹੇਰੇ। ੨੬੭।","roman":"Daan lahai jeea ko ham hoon hasi kaanh kahee tumro tan here | 267 |","meaning_en":"","page":374}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":374},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":374},{"type":"verse","number":[268],"number_text":"੨੬੮।","page":374,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਜਬੈ ਗੋਪੀ ਸਭੈ ਦੇਖਿਯੋ ਨੈਨ ਨਚਾਤ।","roman":"Kaanh jabai gopee sabhai dekhiyo nain nachaat |","meaning_en":"","page":374},{"gurmukhi":"ਹ੍ਵੈ ਪ੍ਰਸੰਨਿ ਕਹਨੇ ਲਗੀ ਸਭੈ ਸੁਧਾ ਸੀ ਬਾਤ। ੨੬੮।","roman":"Hvai prasanni kahne lagee sabhai sudhaa see baat | 268 |","meaning_en":"","page":374}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"","page":375},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":375},{"type":"verse","number":[269],"number_text":"੨੬੯।","page":375,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਹਿਕ੍ਰਮ ਥੋਰੀ ਤੁਮੈ ਖੇਲਹੁ ਨ ਅਪਨੋ ਘਰ ਕਾਹੋ।","roman":"Kaanh bahikram thoree tumai khelhu na apno ghar kaaho |","meaning_en":"","page":375},{"gurmukhi":"ਨੰਦ ਸੁਨੈ ਜਸੁਧਾ ਤਪਤੈ ਤਿਹ ਤੇ ਤੁਮ ਕਾਨ੍ਹ ਭਏ ਹਰਕਾ ਹੋ।","roman":"Nand sunai jasudhaa taptai tih te tum kaanh bhae harkaa ho |","meaning_en":"","page":375},{"gurmukhi":"ਨੇਹੁੰ ਲਗੈ ਨਹ ਜੋਰ ਭਏ ਤੁਮ ਨੇਹੁ ਲਗਾਵਤ ਹੋ ਬਰ ਕਾਹੋ।","roman":"Nehun lagai nah jor bhae tum nehu lagaavat ho bar kaaho |","meaning_en":"","page":375},{"gurmukhi":"ਲੇਹੁ ਕਹਾ ਇਨ ਬਾਤਨ ਤੇ ਰਸ ਜਾਨਤ ਕਾ ਅਜਹੂੰ ਲਰਕਾ ਹੋ। ੨੬੯।","roman":"Lehu kahaa in baatan te ras jaanat kaa ajhoon larkaa ho | 269 |","meaning_en":"","page":375}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":375},{"type":"verse","number":[270],"number_text":"੨੭੦।","page":375,"lines":[{"gurmukhi":"ਕਮਲ ਸੇ ਆਨਨ ਕੁਰੰਗਨ ਸੇ ਨੇਤ੍ਰਨ ਸੋ ਤਨ ਕੀ ਪ੍ਰਭਾ ਮੈ ਸਾਰੇ ਭਾਵਨ ਸੋ ਭਰੀਆ।","roman":"Kamal se aanan kurangan se netran so tan kee prabhaa mai saare bhaavan so bhareeaa |","meaning_en":"","page":375},{"gurmukhi":"ਰਾਜਤ ਹੈ ਗੁਪੀਆ ਪ੍ਰਸੰਨ ਭਈ ਐਸੀ ਭਾਤਿ ਚੰਦ੍ਰਮਾ ਚਰ੍ਹੈ ਤੇ ਜਿਉ ਬਿਰਾਜੈ ਸੇਤ ਹਰੀਆ।","roman":"Raajat hai gupeeaa prasann bhaee aisee bhaati chandramaa charhai te jiu biraajai set hareeaa |","meaning_en":"","page":375},{"gurmukhi":"ਰਸ ਹੀ ਕੀ ਬਾਤੈ ਰਸ ਰੀਤਿ ਹੀ ਕੇ ਪ੍ਰੇਮ ਹੂੰ ਮੈ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਸਾਥ ਕਾਨ੍ਹ ਜੂ ਕੇ ਖਰੀਆ।","roman":"Ras hee kee baatai ras reeti hee ke prem hoon mai kahai kabi syaam saath kaanh joo ke khareeaa |","meaning_en":"","page":375},{"gurmukhi":"ਮਦਨ ਕੇ ਹਾਰਨ ਬਨਾਇਬੇ ਕੇ ਕਾਜ ਮਾਨੋ ਹਿਤ ਕੈ ਪਰੋਵਤ ਹੈ ਮੋਤਿਨ ਕੀ ਲਰੀਆ। ੨੭੦।","roman":"Madan ke haaran banaaibe ke kaaj maano hit kai parovat hai motin kee lareeaa | 270 |","meaning_en":"","page":375}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":375},{"type":"verse","number":[271],"number_text":"੨੭੧।","page":375,"lines":[{"gurmukhi":"ਕਾਹੇ ਕੋ ਕਾਨ੍ਹ ਜੂ ਕਾਮ ਕੇ ਬਾਨ ਲਗਾਵਤ ਹੋ ਤਨ ਕੇ ਧਨੁ ਭਉਹੈ।","roman":"Kaahe ko kaanh joo kaam ke baan lagaavat ho tan ke dhanu bhauhai |","meaning_en":"","page":375},{"gurmukhi":"ਕਾਹੇ ਕਉ ਨੇਹੁ ਲਗਾਵਤ ਹੋ ਮੁਸਕਾਵਤ ਹੋ ਚਲਿ ਆਵਤ ਸਉਹੈ।","roman":"Kaahe kau nehu lagaavat ho muskaavat ho chali aavat sauhai |","meaning_en":"","page":375},{"gurmukhi":"ਕਾਹੇ ਕਉ ਪਾਗ ਧਰੋ ਤਿਰਛੀ ਅਰੁ ਕਾਹੇ ਭਰੋ ਤਿਰਛੀ ਤੁਮ ਗਉਹੈ।","roman":"Kaahe kau paag dharo tirchhee aru kaahe bharo tirchhee tum gauhai |","meaning_en":"","page":375},{"gurmukhi":"ਕਾਹੇ ਰਿਝਾਵਤ ਹੌ ਮਨ ਭਾਵਤ ਆਹਿ ਦਿਵਵਾਤ ਹੈ ਹਮ ਸਉਹੈ। ੨੭੧।","roman":"Kaahe rijhaavat hau man bhaavat aahi divvaat hai ham sauhai | 271 |","meaning_en":"","page":375}]},{"type":"verse","number":[272],"number_text":"੨੭੨।","page":375,"lines":[{"gurmukhi":"ਬਾਤ ਸੁਨੀ ਹਰਿ ਕੀ ਜਬ ਸ੍ਰਉਨਨ ਰੀਝ ਹਸੀ ਸਭ ਹੀ ਬ੍ਰਿਜ ਬਾਮੈ।","roman":"Baat sunee hari kee jab sraunan reejh hasee sabh hee brij baamai |","meaning_en":"","page":375},{"gurmukhi":"ਠਾਢੀ ਭਈ ਤਰੁ ਤੀਰ ਤਬੈ ਹਰੂਏ ਹਰੂਏ ਚਲ ਕੈ ਗਜ ਗਾਮੈ।","roman":"Thaadhee bhaee taru teer tabai harooe harooe chal kai gaj gaamai |","meaning_en":"","page":375},{"gurmukhi":"ਬੇਰਿ ਬਨੇ ਤਿਨ ਨੇਤ੍ਰਨ ਕੇ ਜਨੁ ਮੈਨ ਬਨਾਇ ਧਰੇ ਇਹ ਦਾਮੈ।","roman":"Beri bane tin netran ke janu main banaai dhare ih daamai |","meaning_en":"","page":375},{"gurmukhi":"ਸ੍ਯਾਮ ਰਸਾਤੁਰ ਪੇਖਤ ਯੌ ਜਿਮ ਟੂਟਤ ਬਾਜ ਛੁਧਾ ਜੁਤ ਤਾਮੈ। ੨੭੨।","roman":"Syaam rasaatur pekhat yau jim tootat baaj chhudhaa jut taamai | 272 |","meaning_en":"","page":375}]},{"type":"verse","number":[273],"number_text":"੨੭੩।","page":375,"lines":[{"gurmukhi":"ਕਾਮ ਸੇ ਰੂਪ ਕਲਾਨਿਧਿ ਸੇ ਮੁਖ ਕੀਰ ਸੇ ਨਾਕ ਕੁਰੰਗ ਸੇ ਨੈਨਨ।","roman":"Kaam se roop kalaanidhi se mukh keer se naak kurang se nainan |","meaning_en":"","page":375},{"gurmukhi":"ਕੰਚਨ ਸੇ ਤਨ ਦਾਰਿਮ ਦਾਤ ਕਪੋਤ ਸੇ ਕੰਠ ਸੁ ਕੋਕਿਲ ਬੈਨਨ।","roman":"Kanchan se tan daarim daat kapot se kanth su kokil bainan |","meaning_en":"","page":375},{"gurmukhi":"ਕਾਨ੍ਹ ਲਗਿਯੋ ਕਹਨੇ ਤਿਨ ਸੋ ਹਸਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਸਹਾਇਕ ਧੈਨਨ।","roman":"Kaanh lagiyo kahne tin so hasi kai kabi syaam sahaaik dhainan |","meaning_en":"","page":375},{"gurmukhi":"ਮੋਹਿ ਲਯੋ ਸਭ ਹੀ ਮਨੁ ਮੇਰੋ ਸੁ ਭਉਹ ਨਚਾਇ ਤੁਮੈ ਸੰਗ ਸੈਨਨ। ੨੭੩।","roman":"Mohi layo sabh hee manu mero su bhauh nachaai tumai sang sainan | 273 |","meaning_en":"","page":375}]},{"type":"verse","number":[274],"number_text":"੨੭੪।","page":375,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਬਡੇ ਰਸ ਕੇ ਹਿਰੀਆ ਸਬ ਹੀ ਜਲ ਬੀਚ ਅਚਾਨਕ ਹੇਰੀ।","roman":"Kaanh bade ras ke hireeaa sab hee jal beech achaanak heree |","meaning_en":"","page":375},{"gurmukhi":"ਸਉਹ ਤੁਮੈ ਜਸੁਧਾ ਕਹੁ ਬਾਤ ਕਿਸਾਰਥ ਕੌ ਇਹ ਜਾ ਹਮ ਘੇਰੀ।","roman":"Sauh tumai jasudhaa kahu baat kisaarath kau ih jaa ham gheree |","meaning_en":"","page":375},{"gurmukhi":"ਦੇਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਹਮਰੇ ਪਟ ਹੋਹਿੰ ਸਭੈ ਤੁਮਰੀ ਹਮ ਚੇਰੀ।","roman":"Dehu kahiyo sabh hee hamre pat hohin sabhai tumree ham cheree |","meaning_en":"","page":376},{"gurmukhi":"ਕੈਸੇ ਪ੍ਰਨਾਮ ਕਰੈ ਤੁਮ ਕੋ ਅਤਿ ਲਾਜ ਕਰੈ ਹਰਿ ਜੀ ਹਮ ਤੇਰੀ। ੨੭੪।","roman":"Kaise pranaam karai tum ko ati laaj karai hari jee ham teree | 274 |","meaning_en":"","page":376}]},{"type":"verse","number":[275],"number_text":"੨੭੫।","page":376,"lines":[{"gurmukhi":"ਪਾਪ ਕਰਿਯੋ ਹਰਿ ਕੈ ਤੁਮਰੇ ਪਟ ਅਉ ਤਰੁ ਪੈ ਚੜਿ ਸੀਤ ਸਹਾ ਹੈ।","roman":"Paap kariyo hari kai tumre pat au taru pai chari seet sahaa hai |","meaning_en":"","page":376},{"gurmukhi":"ਜੋ ਹਮ ਪ੍ਰੇਮ ਛਕੇ ਅਤਿ ਹੀ ਤੁਮ ਕੋ ਹਮ ਢੂੰਢਤ ਢੂੰਢ ਲਹਾ ਹੈ।","roman":"Jo ham prem chhake ati hee tum ko ham dhoondhat dhoondh lahaa hai |","meaning_en":"","page":376},{"gurmukhi":"ਜੋਰ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਸਉਹ ਲਗੈ ਤੁਮ ਮੇਰੀ ਹਹਾ ਹੈ।","roman":"Jor pranaam karo ham ko kar sauh lagai tum meree hahaa hai |","meaning_en":"","page":376},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਬਾਤ ਸੁਨੋ ਸੁਭ ਚਾਰ ਭਈ ਤੁ ਬਿਚਾਰ ਕਹਾ ਹੈ। ੨੭੫।","roman":"Kaanh kahee hasi baat suno subh chaar bhaee tu bichaar kahaa hai | 275 |","meaning_en":"","page":376}]},{"type":"verse","number":[276],"number_text":"੨੭੬।","page":376,"lines":[{"gurmukhi":"ਸੰਕ ਕਰੋ ਹਮ ਤੇ ਨ ਕਛੂ ਅਰੁ ਲਾਜ ਕਛੂ ਜੀਅ ਮੈ ਨਹੀ ਕੀਜੈ।","roman":"Sank karo ham te na kachhoo aru laaj kachhoo jeea mai nahee keejai |","meaning_en":"","page":376},{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਮ ਕੋ ਕਰ ਦਾਸਨ ਕੀ ਬਿਨਤੀ ਸੁਨਿ ਲੀਜੈ।","roman":"Jori pranaam karo ham ko kar daasan kee bintee suni leejai |","meaning_en":"","page":376},{"gurmukhi":"ਕਾਨ੍ਹ ਕਹੀ ਹਸਿ ਕੈ ਤਿਨ ਸੋ ਤੁਮਰੇ ਮ੍ਰਿਗ ਸੇ ਦ੍ਰਿਗ ਦੇਖਤ ਜੀਜੈ।","roman":"Kaanh kahee hasi kai tin so tumre mrig se drig dekhat jeejai |","meaning_en":"","page":376},{"gurmukhi":"ਡੇਰਨ ਨਾਹਿ ਕਹੈ ਤੁਮਰੇ ਇਹ ਤੇ ਤੁਮਰੋ ਕਛੂ ਨਾਹਿਨ ਛੀਜੈ। ੨੭੬।","roman":"Deran naahi kahai tumre ih te tumro kachhoo naahin chheejai | 276 |","meaning_en":"","page":376}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":376},{"type":"verse","number":[277],"number_text":"੨੭੭।","page":376,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਜਬੈ ਪਟ ਨ ਦਏ ਤਬ ਗੋਪੀ ਸਭ ਹਾਰਿ।","roman":"Kaanh jabai pat na dae tab gopee sabh haari |","meaning_en":"","page":376},{"gurmukhi":"ਕਾਨ੍ਹਿ ਕਹੈ ਸੋ ਕੀਜੀਐ ਕੀਨੋ ਇਹੈ ਬਿਚਾਰ। ੨੭੭।","roman":"Kaanhi kahai so keejeeai keeno ihai bichaar | 277 |","meaning_en":"","page":376}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":376},{"type":"verse","number":[278],"number_text":"੨੭੮।","page":376,"lines":[{"gurmukhi":"ਜੋਰਿ ਪ੍ਰਨਾਮ ਕਰੋ ਹਰਿ ਕੋ ਕਰ ਆਪਸ ਮੈ ਕਹਿ ਕੈ ਮੁਸਕਾਨੀ।","roman":"Jori pranaam karo hari ko kar aapas mai kahi kai muskaanee |","meaning_en":"","page":376},{"gurmukhi":"ਸ੍ਯਾਮ ਲਗੀ ਕਹਨੇ ਮੁਖ ਤੇ ਸਭ ਹੀ ਗੁਪੀਆ ਮਿਲਿ ਅੰਮ੍ਰਿਤ ਬਾਨੀ।","roman":"Syaam lagee kahne mukh te sabh hee gupeeaa mili anmrit baanee |","meaning_en":"","page":376},{"gurmukhi":"ਹੋਹੁ ਪ੍ਰਸੰਨ੍ਯ ਕਹਿਯੋ ਹਮ ਪੈ ਕਰੁ ਬਾਤ ਕਹੀ ਤੁਮ ਸੋ ਹਮ ਮਾਨੀ।","roman":"Hohu prasanny kahiyo ham pai karu baat kahee tum so ham maanee |","meaning_en":"","page":376},{"gurmukhi":"ਅੰਤਰ ਨਾਹਿ ਰਹਿਯੋ ਇਹ ਜਾ ਅਬ ਸੋਊ ਭਲੀ ਤੁਮ ਜੋ ਮਨਿ ਭਾਨੀ। ੨੭੮।","roman":"Antar naahi rahiyo ih jaa ab so'oo bhalee tum jo mani bhaanee | 278 |","meaning_en":"","page":376}]},{"type":"verse","number":[279],"number_text":"੨੭੯।","page":376,"lines":[{"gurmukhi":"ਕਾਮ ਕੇ ਬਾਨ ਬਨੀ ਬਰਛੀ ਭਰੁਟੇ ਧਨੁ ਸੇ ਦ੍ਰਿਗ ਸੁੰਦਰ ਤੇਰੇ।","roman":"Kaam ke baan banee barchhee bharute dhanu se drig sundar tere |","meaning_en":"","page":376},{"gurmukhi":"ਆਨਨ ਹੈ ਸਸਿ ਸੋ ਅਲਕੈ ਹਰਿ ਮੋਹਿ ਰਹੈ ਮਨ ਰੰਚਕ ਹੇਰੇ।","roman":"Aanan hai sasi so alkai hari mohi rahai man ranchak here |","meaning_en":"","page":376},{"gurmukhi":"ਤਉ ਤੁਮ ਸਾਥ ਕਰੀ ਬਿਨਤੀ ਜਬ ਕਾਮ ਕਰਾ ਉਪਜੀ ਜੀਅ ਮੇਰੇ।","roman":"Tau tum saath karee bintee jab kaam karaa upjee jeea mere |","meaning_en":"","page":376},{"gurmukhi":"ਚੁੰਬਨ ਦੇਹੁ ਕਹਿਓ ਸਭ ਹੀ ਮੁਖ ਸਉਹ ਹਮੈ ਕਹਿ ਹੈ ਨਹਿ ਡੇਰੇ। ੨੭੯।","roman":"Chunban dehu kahio sabh hee mukh sauh hamai kahi hai nahi dere | 279 |","meaning_en":"","page":376}]},{"type":"verse","number":[280],"number_text":"੨੮੦।","page":376,"lines":[{"gurmukhi":"ਹੋਇ ਪ੍ਰਸੰਨ੍ਯ ਸਭੈ ਗੁਪੀਆ ਮਿਲਿ ਮਾਨ ਲਈ ਜੋਊ ਕਾਨ੍ਹ ਕਹੀ ਹੈ।","roman":"Hoi prasanny sabhai gupeeaa mili maan laee jo'oo kaanh kahee hai |","meaning_en":"","page":376},{"gurmukhi":"ਜੋਰਿ ਹੁਲਾਸ ਬਢਿਯੋ ਜੀਅ ਮੈ ਗਿਨਤੀ ਸਰਿਤਾ ਮਗ ਨੇਹ ਬਹੀ ਹੈ।","roman":"Jori hulaas badhiyo jeea mai gintee saritaa mag neh bahee hai |","meaning_en":"","page":376},{"gurmukhi":"ਸੰਕ ਛੁਟੀ ਦੁਹੂੰ ਕੇ ਮਨ ਤੇ ਹਸਿ ਕੈ ਹਰਿ ਤੋ ਇਹ ਬਾਤ ਕਹੀ ਹੈ।","roman":"Sank chhutee duhoon ke man te hasi kai hari to ih baat kahee hai |","meaning_en":"","page":376},{"gurmukhi":"ਬਾਤ ਸੁਨੋ ਹਮਰੀ ਤੁਮ ਹੂੰ ਹਮ ਕੋ ਨਿਧਿ ਆਨੰਦ ਆਜ ਲਹੀ ਹੈ। ੨੮੦।","roman":"Baat suno hamree tum hoon ham ko nidhi aanand aaj lahee hai | 280 |","meaning_en":"","page":376}]},{"type":"verse","number":[281],"number_text":"੨੮੧।","page":377,"lines":[{"gurmukhi":"ਤਉ ਫਿਰਿ ਬਾਤ ਕਹੀ ਉਨ ਹੂੰ ਸੁਨਿ ਰੀ ਹਰਿ ਜੂ ਪਿਖਿ ਬਾਤ ਕਹੀ।","roman":"Tau phiri baat kahee un hoon suni ree hari joo pikhi baat kahee |","meaning_en":"","page":377},{"gurmukhi":"ਸੁਨਿ ਜੋਰ ਹੁਲਾਸ ਬਢਿਓ ਜੀਅ ਮੈ ਗਿਨਤੀ ਸਰਤਾ ਮਗ ਨੇਹ ਬਹੀ।","roman":"Suni jor hulaas badhio jeea mai gintee sartaa mag neh bahee |","meaning_en":"","page":377},{"gurmukhi":"ਅਬ ਸੰਕ ਛੁਟੀ ਇਨ ਕੈ ਮਨ ਕੀ ਤਬ ਹੀ ਹਸਿ ਕੈ ਇਹ ਬਾਤ ਕਹੀ।","roman":"Ab sank chhutee in kai man kee tab hee hasi kai ih baat kahee |","meaning_en":"","page":377},{"gurmukhi":"ਅਬ ਸਤਿ ਭਯੋ ਹਮ ਕੌ ਦੁਰਗਾ ਬਰੁ ਮਾਤ ਸਦਾ ਇਹ ਸਤਿ ਸਹੀ। ੨੮੧।","roman":"Ab sati bhayo ham kau durgaa baru maat sadaa ih sati sahee | 281 |","meaning_en":"","page":377}]},{"type":"verse","number":[282],"number_text":"੨੮੨।","page":377,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਤਬੈ ਕਰ ਕੇਲ ਤਿਨੋ ਸੰਗਿ ਪੈ ਪਟ ਦੇ ਕਰਿ ਛੋਰ ਦਈ ਹੈ।","roman":"Kaanh tabai kar kel tino sangi pai pat de kari chhor daee hai |","meaning_en":"","page":377},{"gurmukhi":"ਹੋਇ ਇਕਤ੍ਰ ਤਬੈ ਗੁਪੀਆ ਸਭ ਚੰਡਿ ਸਰਾਹਤ ਧਾਮ ਗਈ ਹੈ।","roman":"Hoi ikatr tabai gupeeaa sabh chandi saraahat dhaam gaee hai |","meaning_en":"","page":377},{"gurmukhi":"ਆਨੰਦ ਅਤਿ ਸੁ ਬਢਿਯੋ ਤਿਨ ਕੇ ਜੀਅ ਸੋ ਉਪਮਾ ਕਬਿ ਚੀਨ ਲਈ ਹੈ।","roman":"Aanand ati su badhiyo tin ke jeea so upmaa kabi cheen laee hai |","meaning_en":"","page":377},{"gurmukhi":"ਜਿਉ ਅਤਿ ਮੇਘ ਪਰੈ ਧਰਿ ਪੈ ਧਰਿ ਜ੍ਯੋ ਸਬਜੀ ਸੁਭ ਰੰਗ ਭਈ ਹੈ। ੨੮੨।","roman":"Jiu ati megh parai dhari pai dhari jyo sabjee subh rang bhaee hai | 282 |","meaning_en":"","page":377}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ","gurmukhi":"ਗੋਪੀ ਬਾਚ","roman":"Gopee baach","meaning_en":"","page":377},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":377},{"type":"verse","number":[283],"number_text":"੨੮੩।","page":377,"lines":[{"gurmukhi":"ਧੰਨਿ ਚੰਡਿਕਾ ਮਾਤ ਹਮੈ ਬਰੁ ਇਹ ਦਯੋ।","roman":"Dhanni chandikaa maat hamai baru ih dayo |","meaning_en":"","page":377},{"gurmukhi":"ਧੰਨਿ ਦਿਯੋਸ ਹੈ ਆਜ ਕਾਨ੍ਹ ਹਮ ਮਿਤ ਭਯੋ।","roman":"Dhanni diyos hai aaj kaanh ham mit bhayo |","meaning_en":"","page":377},{"gurmukhi":"ਦੁਰਗਾ ਅਬ ਇਹ ਕਿਰਪਾ ਹਮ ਪਰ ਕੀਜੀਐ।","roman":"Durgaa ab ih kirpaa ham par keejeeai |","meaning_en":"","page":377},{"gurmukhi":"ਹੋ ਕਾਨਰ ਕੋ ਬਹੁ ਦਿਵਸ ਸੁ ਦੇਖਨ ਦੀਜੀਐ। ੨੮੩।","roman":"Ho kaanar ko bahu divas su dekhan deejeeai | 283 |","meaning_en":"","page":377}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਦੇਵੀ ਜੂ ਸੋ","roman":"Gopee baach devee joo so","meaning_en":"","page":377},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":377},{"type":"verse","number":[284],"number_text":"੨੮੪।","page":377,"lines":[{"gurmukhi":"ਚੰਡਿ ਕ੍ਰਿਪਾ ਹਮ ਪੈ ਕਰੀਐ ਹਮਰੋ ਅਤਿ ਪ੍ਰੀਤਮ ਹੋਇ ਕਨਈਯਾ।","roman":"Chandi kripaa ham pai kareeai hamro ati preetam hoi kanaeeyaa |","meaning_en":"","page":377},{"gurmukhi":"ਪਾਇ ਪਰੇ ਹਮ ਹੂੰ ਤੁਮਰੇ ਹਮ ਕਾਨ੍ਹ ਮਿਲੈ ਮੁਸਲੀਧਰ ਭਈਯਾ।","roman":"Paai pare ham hoon tumre ham kaanh milai musleedhar bhaeeyaa |","meaning_en":"","page":377},{"gurmukhi":"ਯਾਹੀ ਤੇ ਦੈਤ ਸੰਘਾਰਨ ਨਾਮ ਕਿਧੋ ਤੁਮਰੋ ਸਭ ਹੀ ਜੁਗ ਗਈਯਾ।","roman":"Yaahee te dait sanghaaran naam kidho tumro sabh hee jug gaeeyaa |","meaning_en":"","page":377},{"gurmukhi":"ਤਉ ਹਮ ਪਾਇ ਪਰੀ ਤੁਮਰੇ ਜਬ ਹੀ ਤੁਮ ਤੇ ਇਹ ਪੈ ਬਰ ਪਈਯਾ। ੨੮੪।","roman":"Tau ham paai paree tumre jab hee tum te ih pai bar paeeyaa | 284 |","meaning_en":"","page":377}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":377},{"type":"verse","number":[285],"number_text":"੨੮੫।","page":377,"lines":[{"gurmukhi":"ਦੈਤਨ ਕੀ ਮ੍ਰਿਤ ਸਾਧ ਸੇਵਕ ਕੀ ਬਰਤਾ ਤੂ ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਆਦਿ ਅੰਤ ਹੂੰ ਕੀ ਕਰਤਾ।","roman":"Daitan kee mrit saadh sevak kee bartaa too kahai kabi syaam aadi ant hoon kee kartaa |","meaning_en":"","page":377},{"gurmukhi":"ਦੀਜੈ ਬਰਦਾਨ ਮੋਹਿ ਕਰਤ ਬਿਨੰਤੀ ਤੋਹਿ ਕਾਨ੍ਹ ਬਰੁ ਦੀਜੈ ਦੋਖ ਦਾਰਦ ਕੀ ਹਰਤਾ।","roman":"Deejai bardaan mohi karat binantee tohi kaanh baru deejai dokh daarad kee hartaa |","meaning_en":"","page":377},{"gurmukhi":"ਤੂ ਹੀ ਪਾਰਬਤੀ ਅਸਟ ਭੁਜੀ ਤੁਹੀ ਦੇਵੀ ਤੁਹੀ ਤੁਹੀ ਰੂਪ ਛੁਧਾ ਤੁਹੀ ਪੇਟ ਹੂੰ ਕੀ ਭਰਤਾ।","roman":"Too hee paarabtee asat bhujee tuhee devee tuhee tuhee roop chhudhaa tuhee pet hoon kee bhartaa |","meaning_en":"","page":377},{"gurmukhi":"ਤੁਹੀ ਰੂਪ ਲਾਲ ਤੁਹੀ ਸੇਤ ਰੂਪ ਪੀਤ ਤੁਹੀ ਤੁਹੀ ਰੂਪ ਧਰਾ ਕੋ ਹੈ ਤੁਹੀ ਆਪ ਕਰਤਾ।੨੮੫।","roman":"Tuhee roop laal tuhee set roop peet tuhee tuhee roop dharaa ko hai tuhee aap kartaa | 285 |","meaning_en":"","page":377}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":377},{"type":"verse","number":[286],"number_text":"੨੮੬।","page":377,"lines":[{"gurmukhi":"ਬਾਹਨਿ ਸਿੰਘ ਭੁਜਾ ਅਸਟਾ ਜਿਹ ਚਕ੍ਰ ਤ੍ਰਿਸੂਲ ਗਦਾ ਕਰ ਮੈ।","roman":"Baahni singh bhujaa astaa jih chakr trisool gadaa kar mai |","meaning_en":"","page":377},{"gurmukhi":"ਬਰਛੀ ਸਰ ਢਾਲ ਕਮਾਨ ਨਿਖੰਗ ਧਰੇ ਕਟਿ ਜੋ ਬਰ ਹੈ ਬਰਮੈ।","roman":"Barchhee sar dhaal kamaan nikhang dhare kati jo bar hai barmai |","meaning_en":"","page":377},{"gurmukhi":"ਗੁਪੀਆ ਸਭ ਸੇਵ ਕਰੈ ਤਿਹ ਕੀ ਚਿਤ ਦੈ ਤਿਹ ਮੈ ਹਿਤੁ ਕੈ ਹਰਿ ਮੈ।","roman":"Gupeeaa sabh sev karai tih kee chit dai tih mai hitu kai hari mai |","meaning_en":"","page":378},{"gurmukhi":"ਪੁਨਿ ਅਛਤ ਧੂਪ ਪੰਚਾਮ੍ਰਿਤ ਦੀਪ ਜਗਾਵਤ ਹਾਰ ਡਰੈ ਗਰ ਮੈ। ੨੮੬।","roman":"Puni achhat dhoop panchaamrit deep jagaavat haar darai gar mai | 286 |","meaning_en":"","page":378}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":378},{"type":"verse","number":[287],"number_text":"੨੮੭।","page":378,"lines":[{"gurmukhi":"ਤੋਹੀ ਕੋ ਸੁਨੈ ਹੈ ਜਾਪ ਤੇਰੋ ਹੀ ਜਪੈ ਹੈ ਧਿਆਨ ਤੇਰੋ ਹੀ ਧਰੈ ਹੈ ਨ ਜਪੈ ਹੈ ਕਾਹੂੰ ਆਨ ਕੋ।","roman":"Tohee ko sunai hai jaap tero hee japai hai dhiaan tero hee dharai hai na japai hai kaahoon aan ko |","meaning_en":"","page":378},{"gurmukhi":"ਤੇਰੋ ਗੁਨ ਗੈ ਹੈ ਹਮ ਤੇਰੇ ਹੀ ਕਹੈ ਹੈ ਫੂਲ ਤੋਹੀ ਪੈ ਡਰੈ ਹੈ ਸਭ ਰਾਖੈ ਤੇਰੇ ਮਾਨ ਕੋ।","roman":"Tero gun gai hai ham tere hee kahai hai phool tohee pai darai hai sabh raakhai tere maan ko |","meaning_en":"","page":378},{"gurmukhi":"ਜੈਸੇ ਬਰੁ ਦੀਨੋ ਹਮੈ ਹੋਇ ਕੈ ਪ੍ਰਸੰਨਿ ਪਾਛੈ ਤੈਸੇ ਬਰ ਦੀਜੈ ਹਮੈ ਕਾਨ੍ਹ ਸੁਰ ਗ੍ਯਾਨ ਕੋ।","roman":"Jaise baru deeno hamai hoi kai prasanni paachhai taise bar deejai hamai kaanh sur gyaan ko |","meaning_en":"","page":378},{"gurmukhi":"ਦੀਜੀਐ ਬਿਭੂਤਿ ਕੈ ਬਨਾਸਪਤੀ ਦੀਜੈ ਕੈਧੋ ਮਾਲਾ ਦੀਜੈ ਮੋਤਿਨ ਕੈ ਮੁੰਦ੍ਰਾ ਦੀਜੈ ਕਾਨ੍ਹਕੋ।੨੮੭।","roman":"Deejeeai bibhooti kai banaasaptee deejai kaidho maalaa deejai motin kai mundraa deejai kaanhako | 287 |","meaning_en":"","page":378}]},{"type":"heading","kind":"speaker","name":"ਦੇਵੀ ਬਾਚ","gurmukhi":"ਦੇਵੀ ਬਾਚ","roman":"Devee baach","meaning_en":"","page":378},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":378},{"type":"verse","number":[288],"number_text":"੨੮੮।","page":378,"lines":[{"gurmukhi":"ਤੋ ਹਸ ਬਾਤ ਕਹੀ ਦੁਰਗਾ ਹਮ ਤੋ ਤੁਮ ਕੋ ਹਰਿ ਕੋ ਬਰੁ ਦੈ ਹੈ।","roman":"To has baat kahee durgaa ham to tum ko hari ko baru dai hai |","meaning_en":"","page":378},{"gurmukhi":"ਹੋਹੁ ਪ੍ਰਸੰਨਿ ਸਭੈ ਮਨ ਮੈ ਤੁਮ ਸਤ ਕਹਿਯੋ ਨਹੀ ਝੂਠ ਕਹੈ ਹੈ।","roman":"Hohu prasanni sabhai man mai tum sat kahiyo nahee jhooth kahai hai |","meaning_en":"","page":378},{"gurmukhi":"ਕਾਨਹਿ ਕੋ ਸੁਖ ਹੋ ਤੁਮ ਕੋ ਹਮ ਸੋ ਸੁਖ ਸੋ ਅਖੀਆ ਭਰਿ ਲੈ ਹੈ।","roman":"Kaanhi ko sukh ho tum ko ham so sukh so akheeaa bhari lai hai |","meaning_en":"","page":378},{"gurmukhi":"ਜਾਹੁ ਕਹਿਯੋ ਸਭ ਹੀ ਤੁਮ ਡੇਰਨ ਕਾਲ੍ਹ ਵਹੈ ਬਰੁ ਕੋ ਤੁਮ ਪੈ ਹੈ। ੨੮੮।","roman":"Jaahu kahiyo sabh hee tum deran kaalh vahai baru ko tum pai hai | 288 |","meaning_en":"","page":378}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":378},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":378},{"type":"verse","number":[289],"number_text":"੨੮੯।","page":378,"lines":[{"gurmukhi":"ਹ੍ਵੈ ਪ੍ਰਸੰਨ੍ਯ ਸਭ ਬ੍ਰਿਜ ਬਧੂ ਤਿਹ ਕੋ ਸੀਸ ਨਿਵਾਇ।","roman":"Hvai prasanny sabh brij badhoo tih ko sees nivaai |","meaning_en":"","page":378},{"gurmukhi":"ਪਰਿ ਪਾਇਨ ਕਰਿ ਬੇਨਤੀ ਚਲੀ ਗ੍ਰਿਹਨ ਕੌ ਧਾਇ। ੨੮੯।","roman":"Pari paain kari bentee chalee grihan kau dhaai | 289 |","meaning_en":"","page":378}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":378},{"type":"verse","number":[290],"number_text":"੨੯੦।","page":378,"lines":[{"gurmukhi":"ਆਪਸ ਮੈ ਕਰ ਜੋਰਿ ਸਭੈ ਗੁਪੀਆ ਚਲਿ ਧਾਮ ਗਈ ਹਰਖਾਨੀ।","roman":"Aapas mai kar jori sabhai gupeeaa chali dhaam gaee harkhaanee |","meaning_en":"","page":378},{"gurmukhi":"ਰੀਝ ਦਯੋ ਹਮ ਕੋ ਦੁਰਗਾ ਬਰੁ ਸ੍ਯਾਮ ਚਲੀ ਕਹਤੀ ਇਹ ਬਾਨੀ।","roman":"Reejh dayo ham ko durgaa baru syaam chalee kahtee ih baanee |","meaning_en":"","page":378},{"gurmukhi":"ਆਨੰਦ ਮਤ ਭਰੀ ਮਦ ਸੋ ਸਭ ਸੁੰਦਰ ਧਾਮਨ ਕੋ ਨਿਜਕਾਨੀ।","roman":"Aanand mat bharee mad so sabh sundar dhaaman ko nijkaanee |","meaning_en":"","page":378},{"gurmukhi":"ਦਾਨ ਦਯੋ ਦਿਜਹੂੰ ਬਹੁਤਿਯੋ ਮਨ ਇਛਤ ਹੈ ਹਰਿ ਹੋ ਹਮ ਜਾਨੀ। ੨੯੦।","roman":"Daan dayo dijhoon bahutiyo man ichhat hai hari ho ham jaanee | 290 |","meaning_en":"","page":378}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":378},{"type":"verse","number":[291],"number_text":"੨੯੧।","page":378,"lines":[{"gurmukhi":"ਸਮੈ ਭਲੈ ਇਕ ਘਾਤ ਸਿਉ ਹ੍ਵੈ ਇਕਤ੍ਰ ਸਭ ਬਾਲ।","roman":"Samai bhalai ik ghaat siu hvai ikatr sabh baal |","meaning_en":"","page":378},{"gurmukhi":"ਅੰਗ ਸਭੈ ਗਿਨਨੈ ਲਗੀ ਕਰਿ ਕੈ ਬਾਤ ਰਸਾਲ। ੨੯੧।","roman":"Ang sabhai ginnai lagee kari kai baat rasaal | 291 |","meaning_en":"","page":378}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":379},{"type":"verse","number":[292],"number_text":"੨੯੨।","page":379,"lines":[{"gurmukhi":"ਕੋਊ ਕਹੈ ਹਰਿ ਕੋ ਮੁਖ ਸੁੰਦਰ ਕੋਊ ਕਹੈ ਸੁਭ ਨਾਕ ਬਨਿਯੋ ਹੈ।","roman":"Ko'oo kahai hari ko mukh sundar ko'oo kahai subh naak baniyo hai |","meaning_en":"","page":379},{"gurmukhi":"ਕੋਊ ਕਹੈ ਕਟਿ ਕੇਹਰਿ ਸੀ ਤਨ ਕੰਚਨ ਸੋ ਰਿਝਿ ਕਾਹੂ ਗਨਿਯੋ ਹੈ।","roman":"Ko'oo kahai kati kehri see tan kanchan so rijhi kaahoo ganiyo hai |","meaning_en":"","page":379},{"gurmukhi":"ਨੈਨ ਕੁਰੰਗ ਸੇ ਕੋਊ ਗਨੈ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਭਨਿਯੋ ਹੈ।","roman":"Nain kurang se ko'oo ganai jasu taa chhabi ko kabi syaam bhaniyo hai |","meaning_en":"","page":379},{"gurmukhi":"ਲੋਗਨ ਮੈ ਜਿਮ ਜੀਵ ਬਨਿਯੋ ਤਿਨ ਕੇ ਤਨ ਮੈ ਤਿਮ ਕਾਨ੍ਹ ਮਨਿਯੋ ਹੈ। ੨੯੨।","roman":"Logan mai jim jeev baniyo tin ke tan mai tim kaanh maniyo hai | 292 |","meaning_en":"","page":379}]},{"type":"verse","number":[293],"number_text":"੨੯੩।","page":379,"lines":[{"gurmukhi":"ਕਾਨ੍ਹ ਕੋ ਪੇਖਿ ਕਲਾਨਿਧਿ ਸੌ ਮੁਖ ਰੀਝ ਰਹੀ ਸਭ ਹੀ ਬ੍ਰਿਜ ਬਾਰਾ।","roman":"Kaanh ko pekhi kalaanidhi sau mukh reejh rahee sabh hee brij baaraa |","meaning_en":"","page":379},{"gurmukhi":"ਮੋਹਿ ਰਹੇ ਭਗਵਾਨ ਉਤੇ ਇਨਹੂੰ ਦੁਰਗਾ ਬਰੁ ਚੇਟਕ ਡਾਰਾ।","roman":"Mohi rahe bhagvaan ute inhoon durgaa baru chetak daaraa |","meaning_en":"","page":379},{"gurmukhi":"ਕਾਨਿ ਟਿਕੈ ਗ੍ਰਿਹ ਅਉਰ ਬਿਖੈ ਤਿਹ ਕੋ ਅਤਿ ਹੀ ਜਸੁ ਸ੍ਯਾਮ ਉਚਾਰਾ।","roman":"Kaani tikai grih aur bikhai tih ko ati hee jasu syaam uchaaraa |","meaning_en":"","page":379},{"gurmukhi":"ਜੀਵ ਇਕਤ੍ਰ ਰਹੈ ਤਿਨ ਕੋ ਇਮ ਟੂਟ ਗਏ ਜਿਉ ਮ੍ਰਿਨਾਲ ਕੀ ਤਾਰਾ। ੨੯੩।","roman":"Jeev ikatr rahai tin ko im toot gae jiu mrinaal kee taaraa | 293 |","meaning_en":"","page":379}]},{"type":"verse","number":[294],"number_text":"੨੯੪।","page":379,"lines":[{"gurmukhi":"ਨੇਹੁ ਲਗਿਯੋ ਇਨ ਕੋ ਹਰਿ ਸੌ ਅਰੁ ਨੇਹੁ ਲਗਿਯੋ ਹਰਿ ਕੋ ਇਨ ਨਾਰੇ।","roman":"Nehu lagiyo in ko hari sau aru nehu lagiyo hari ko in naare |","meaning_en":"","page":379},{"gurmukhi":"ਚੈਨ ਪਰੈ ਦੁਹ ਕੋ ਨਹਿ ਦ੍ਵੈ ਪਲ ਨ੍ਹਾਵਨ ਜਾਵਤ ਹੋਤ ਸਵਾਰੇ।","roman":"Chain parai duh ko nahi dvai pal nhaavan jaavat hot savaare |","meaning_en":"","page":379},{"gurmukhi":"ਸ੍ਯਾਮ ਭਏ ਭਗਵਾਨ ਇਨੈ ਬਸਿ ਦੈਤਨ ਕੇ ਜਿਹ ਤੇ ਦਲ ਹਾਰੇ।","roman":"Syaam bhae bhagvaan inai basi daitan ke jih te dal haare |","meaning_en":"","page":379},{"gurmukhi":"ਖੇਲ ਦਿਖਾਵਤ ਹੈ ਜਗ ਕੌ ਦਿਨ ਥੋਰਨ ਮੈ ਅਬ ਕੰਸ ਪਛਾਰੇ। ੨੯੪।","roman":"Khel dikhaavat hai jag kau din thoran mai ab kans pachhaare | 294 |","meaning_en":"","page":379}]},{"type":"verse","number":[295],"number_text":"੨੯੫।","page":379,"lines":[{"gurmukhi":"ਉਤ ਜਾਗਤ ਸ੍ਯਾਮ ਇਤੈ ਗੁਪੀਆ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਿਤ ਕੈ ਸੰਗਿ ਤਾ ਕੇ।","roman":"Ut jaagat syaam itai gupeeaa kabi syaam kahai hit kai sangi taa ke |","meaning_en":"","page":379},{"gurmukhi":"ਰੀਝ ਰਹੀ ਤਿਹ ਪੈ ਸਭ ਹੀ ਪਿਖਿ ਨੈਨਨ ਸੋ ਫੁਨਿ ਕਾਨ੍ਹਰ ਬਾਕੇ।","roman":"Reejh rahee tih pai sabh hee pikhi nainan so phuni kaanhar baake |","meaning_en":"","page":379},{"gurmukhi":"ਪ੍ਰੇਮ ਛਕੀ ਨ ਪਰੈ ਇਨ ਕੋ ਕਲਿ ਕਾਮ ਬਢਿਯੋ ਅਤਿ ਹੀ ਤਨ ਵਾ ਕੇ।","roman":"Prem chhakee na parai in ko kali kaam badhiyo ati hee tan vaa ke |","meaning_en":"","page":379},{"gurmukhi":"ਖੇਲਹਿ ਪ੍ਰਾਤਹਿ ਕਾਲ ਭਏ ਹਮ ਨਾਹਿ ਲਖੈ ਹਮ ਕੈ ਜਨ ਗਾ ਕੇ। ੨੯੫।","roman":"Khelhi praathi kaal bhae ham naahi lakhai ham kai jan gaa ke | 295 |","meaning_en":"","page":379}]},{"type":"verse","number":[296],"number_text":"੨੯੬।","page":379,"lines":[{"gurmukhi":"ਪ੍ਰਾਤ ਭਯੋ ਚੁਹਲਾਤ ਚਿਰੀ ਜਲਜਾਤ ਖਿਰੇ ਬਨ ਗਾਇ ਛਿਰਾਨੀ।","roman":"Praat bhayo chuhlaat chiree jaljaat khire ban gaai chhiraanee |","meaning_en":"","page":379},{"gurmukhi":"ਗੋਪ ਜਗੇ ਪਤਿ ਗੋਪ ਜਗਿਯੋ ਕਬਿ ਸ੍ਯਾਮ ਜਗੀ ਅਰੁ ਗੋਪਨਿ ਰਾਨੀ।","roman":"Gop jage pati gop jagiyo kabi syaam jagee aru gopni raanee |","meaning_en":"","page":379},{"gurmukhi":"ਜਾਗ ਉਠੇ ਤਬ ਹੀ ਕਰੁਨਾਨਿਧਿ ਜਾਗਿ ਉਠਿਯੋ ਮੁਸਲੀਧਰ ਮਾਨੀ।","roman":"Jaag uthe tab hee karunaanidhi jaagi uthiyo musleedhar maanee |","meaning_en":"","page":379},{"gurmukhi":"ਗੋਪ ਗਏ ਉਤ ਨ੍ਹਾਨ ਕਰੈ ਇਤ ਕਾਨ੍ਹ ਚਲੇ ਗੁਪੀਆ ਨਿਜਕਾਨੀ। ੨੯੬।","roman":"Gop gae ut nhaan karai it kaanh chale gupeeaa nijkaanee | 296 |","meaning_en":"","page":379}]},{"type":"verse","number":[297],"number_text":"੨੯੭।","page":379,"lines":[{"gurmukhi":"ਬਾਤ ਕਹੈ ਰਸ ਕੀ ਹਸ ਕੈ ਨਹਿ ਅਉਰ ਕਥਾ ਰਸ ਕੀ ਕੋਊ ਭਾਖੈ।","roman":"Baat kahai ras kee has kai nahi aur kathaa ras kee ko'oo bhaakhai |","meaning_en":"","page":379},{"gurmukhi":"ਚੰਚਲ ਸ੍ਰੀ ਪਤਿ ਕੇ ਅਪੁਨੇ ਦ੍ਰਿਗ ਮੋਹਿ ਤਿਨੈ ਬਤੀਆ ਇਹ ਆਖੈ।","roman":"Chanchal sree pati ke apune drig mohi tinai bateeaa ih aakhai |","meaning_en":"","page":379},{"gurmukhi":"ਬਾਤ ਨ ਜਾਨਤ ਹੋ ਰਸ ਕੀ ਰਸ ਜਾਨਤ ਸੋ ਨਰ ਜੋ ਰਸ ਗਾਖੈ।","roman":"Baat na jaanat ho ras kee ras jaanat so nar jo ras gaakhai |","meaning_en":"","page":379},{"gurmukhi":"ਪ੍ਰੀਤਿ ਪੜੈ ਕਰਿ ਪ੍ਰੀਤਿ ਕੜੈ ਰਸ ਰੀਤਿਨ ਚੀਤ ਸੁਨੋ ਸੋਈ ਚਾਖੈ। ੨੯੭।","roman":"Preeti parai kari preeti karai ras reetin cheet suno soee chaakhai | 297 |","meaning_en":"","page":379}]},{"type":"heading","kind":"speaker","name":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","gurmukhi":"ਗੋਪੀ ਬਾਚ ਕਾਨ੍ਹ ਸੋ","roman":"Gopee baach kaanh so","meaning_en":"","page":380},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":380},{"type":"verse","number":[298],"number_text":"੨੯੮।","page":380,"lines":[{"gurmukhi":"ਮੀਤ ਕਹੋ ਰਸ ਰੀਤਿ ਸਬੈ ਹਮ ਪ੍ਰੀਤਿ ਭਈ ਸੁਨਬੇ ਬਤੀਆ ਕੀ।","roman":"Meet kaho ras reeti sabai ham preeti bhaee sunbe bateeaa kee |","meaning_en":"","page":380},{"gurmukhi":"ਅਉਰ ਭਈ ਤੁਹਿ ਦੇਖਨਿ ਕੀ ਤੁਮ ਪ੍ਰੀਤਿ ਭਈ ਹਮਰੀ ਛਤੀਆ ਕੀ।","roman":"Aur bhaee tuhi dekhni kee tum preeti bhaee hamree chhateeaa kee |","meaning_en":"","page":380},{"gurmukhi":"ਰੀਝਿ ਲਗੀ ਕਹਨੇ ਮੁਖ ਤੇ ਹਸਿ ਸੁੰਦਰ ਬਾਤ ਇਸੀ ਗਤੀਆ ਕੀ।","roman":"Reejhi lagee kahne mukh te hasi sundar baat isee gateeaa kee |","meaning_en":"","page":380},{"gurmukhi":"ਨੇਹ ਲਗਿਯੋ ਹਰਿ ਸੋ ਭਈ ਮੋਛਨ ਹੋਤਿ ਇਤੀ ਗਤਿ ਹੈ ਸੁ ਤ੍ਰੀਆ ਕੀ। ੨੯੮।","roman":"Neh lagiyo hari so bhaee mochhan hoti itee gati hai su treeaa kee | 298 |","meaning_en":"","page":380}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਦਸਮ ਸਕੰਧ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਚੀਰ ਹਰਨ","roman":"Iti sree dasam sakandh bachitr naatak granthe krisnaavtaare cheer haran","meaning_en":"","page":380},{"gurmukhi":"ਧਿਆਇ ਸਮਾਪਤੰ।","roman":"Dhiaai samaaptan |","meaning_en":"","page":380}],"page":380}});
